using NeonSidekick.App;

namespace NeonSidekick.Help;

/// <summary>
/// What each settings row does, in a sentence or a few (2026-10-02, the user's call: the descriptions live in code, not in an
/// embedded README), for <c>neon_help</c> (<see cref="NeonHelp"/>). Seeded from README's "What it does" columns; a new
/// <see cref="SettingsField"/> needs its line here as it needs its docs/SETTINGS.md row, README's until 2026-10-05 (<c>NeonHelpCatalogTests</c> fails on a field
/// without one). Where the row lives and its default are worked out from the menus' own lists (<see cref="HelpLocation"/>),
/// never written here.
/// </summary>
public static class HelpSettings
{
    /// <summary>The row's purpose, plain text (backticks and <c>*Setting*</c> names kept); on macOS <see cref="HelpMac.Settings"/>' text where it has one (2026-10-06).</summary>
    public static string Describe(SettingsField field) =>
        OperatingSystem.IsMacOS() && HelpMac.Setting(field) is { } mac ? mac : DescribeAsWritten(field);

    /// <summary>The row's purpose as written here, every system's but where <see cref="HelpMac"/> has a Mac text.</summary>
    internal static string DescribeAsWritten(SettingsField field) => field switch
    {
        SettingsField.Profile => "Switches to another profile for this run (each has its own settings, persona, memory, skills and sessions). Each start opens `neon` unless `--profile`, `NEONSIDEKICK_PROFILE` or a desktop shortcut names another.",
        SettingsField.ModelAvatar => "The profile's emoji: it opens each of its replies in place of ●, marks its `/botchat` speaker line and goes before its name in the window title. Enter (or `/avatar`) opens the emoji grid: type to search names and keywords (or paste an emoji), Tab steps the tabs (For you, from the profile's name and persona; Recent; then each Unicode group), Enter on a hand or a person offers its skin tones, 🎲 picks one at random and 🚫 clears it. Other profiles' avatars are marked. `/profile reset` keeps it; `/profile push` and `pull` never copy it.",
        SettingsField.UserAvatar => "Your own emoji: it opens each of your lines in the transcript (the main chat's and `/botchat`'s) in place of ›; the input line keeps › while you type. Enter opens the same emoji grid as *Model avatar*, without its For you tab; 🚫 clears it, back to ›. `/profile reset` keeps it.",
        SettingsField.UserLineStyle => "How your sent line looks in the transcript and on the Web UI's Chat tab: `quiet` (the › in the user color, your words in the body's), `slab` (your line on a faint fill) or `bold` (the whole line bold in the user color).",
        SettingsField.MemoryMode => "What the model may do with long-term memory: `read-write`, `read-only` or `off`. `read-write`: it is offered `save_memory` and `recall_memory`, and every conversation opens with what it remembers. `read-only`: `recall_memory` alone; it reads, never saves (your `/remember` still saves). `off`: no memory at all, and `/remember` is refused. `/memory read-write`, `read-only`, `off` or `on` (read-write), and the buttons on `/memory`'s pane, set it too.",
        SettingsField.LlmUrl => "The server's OpenAI-compatible base URL (`http://127.0.0.1:1234/v1`), `embedded` for the app's own embedded LLM, or `docker:<container>` for a chosen Docker container. `/server` fills it in. Empty: the app scans as *LLM server scan mode* says and, at startup, lets you pick a server, model and reasoning level and saves all three; Esc at that picker takes the first server without saving it.",
        SettingsField.LlmModel => "The model id. Empty takes the first model the server lists. `/model` picks one, and a Docker server serving one model saves its id here when it connects.",
        SettingsField.LlmApiKey => "The bearer token the server expects; leave it empty for a local server that needs none. A key is saved encrypted for your Windows account and shown as `(set, encrypted)`. Typing a new value replaces it (`empty` stays as it is).",
        SettingsField.LlmReasoning => "How hard the model thinks, sent with every request: `none` (thinking off), `low`, `medium`, `high` or `xhigh`. `/reasoning` opens the same list.",
        SettingsField.LlmRequestTimeoutSeconds => "The longest one HTTP request may take (up to 3600 s).",
        SettingsField.LlmTurnTimeoutSeconds => "The longest one whole turn may take, every tool round trip included (up to 21,600 s).",
        SettingsField.TtsOutput => "Reads replies aloud (`/tts`). Code blocks and tables are shown but never read aloud, not even by `/read`.",
        SettingsField.TtsHttpUrl => "The Kokoro-FastAPI base URL (`http://localhost:8880/v1` for a server on this machine), used while *TTS source* is `http`.",
        SettingsField.TtsVoicePreset => "Sets *TTS voice*, *TTS voice 2*, *TTS voice mix (%)* and *TTS speed* in one go. The preset itself is not saved: the row shows the preset those four match, or `(custom)`. Built in: `amanda`, `neon`, `richard`, `hunter`, `larry`, `jack`, `willow`. Your own presets go in the home folder's `voices` folder, one JSON file each; a file named like a built-in replaces it. Forty-one more come with the repo, with samples to listen to.",
        SettingsField.TtsVoice => "The Kokoro voice.",
        SettingsField.TtsVoice2 => "A second voice blended into the first; `(none)` for the first voice alone.",
        SettingsField.TtsVoiceMix => "The first voice's share of the blend (0–100 %).",
        SettingsField.TtsSpeed => "How fast the voice speaks, as a multiplier (0.5–2.0).",
        SettingsField.SttInput => "Turns the microphone on: the push-to-talk key records a spoken message (`/stt`).",
        SettingsField.SttWake => "Saying the wake phrase at the idle line starts listening, with no key (`/stt wake`).",
        SettingsField.SttWakePhrase => "One to three words. It is also the interrupt phrase.",
        SettingsField.SttInterrupt => "Saying the wake phrase while a reply is being spoken cuts it short and listens (`/stt interrupt`).",
        SettingsField.SttInterruptEchoGuard => "Stops the assistant's own voice from triggering an interrupt: what it just spoke is ignored as an echo when it is at least this close to the wake phrase (50–100 %; 100 = the exact phrase only).",
        SettingsField.SttInterruptConfirmMs => "How long the phrase must keep showing in the recognizer's early (interim) results before it counts (0–2000 ms).",
        SettingsField.SttPushToTalkKey => "The key that records: `F1`–`F8`, `Insert`, `Home`, `End`, `PageUp` or `PageDown`.",
        SettingsField.SttWhisperModel => "The Whisper model that turns speech into text: `ggml-tiny.en.bin`, `ggml-base.en.bin` or `ggml-small.en.bin` (downloaded on first use).",
        SettingsField.WorkingDirectory => "The folder the file and GitLib tools work in. Empty means the profile's own `files` folder. Enter opens the `/cwd browse` folder picker; `/cwd <path>` sets a typed path.",
        SettingsField.CopyUserPrompt => "`/copy` includes your prompt above the reply. Off, it copies the reply alone.",
        SettingsField.LlmContextLength => "The model's context window in tokens, used for the usage percentage. 0 takes the server's own figure.",
        SettingsField.ShowImageThumbnails => "Draws a small thumbnail of each picture you send under your line, and of each picture a tool fetches or makes or `/botchat` draws. `/view` and `/imagine` draw theirs either way. A chat brought back by `/sessions` or `/rewind` draws its pictures again where they were (not a `/botchat`'s, nor a camera or screen shot the session did not keep).",
        SettingsField.LlmCompactType => "What `/compact` does: `summary` or `prune`. Either mode first stubs a plan's earlier revisions and the reads of its file, keeping the latest presentation whole. `summary` folds the older turns into one summary written by the model; `prune` replaces their bulky tool results and long call arguments with short stubs and keeps every turn. If the server answers a summary request with no text, the app asks once more over a plainer, smaller transcript; if that is empty too, the compact fails and says why (the context ran out, the model only thought, or it called a tool).",
        SettingsField.LlmCompactKeepRecent => "How many of the most recent user turns a compact keeps word for word (0–24).",
        SettingsField.LlmAutoCompactPercent => "How full the context window may get before the next message compacts it first (1–100; 0 = off). *LLM tool compact mode* acts at the same share during a reply, judged on the next request: the last reported usage plus an estimate of the tool results added since. Both checks leave room for the next reply: the largest reply so far, or the plan file's size while a plan is written, at most a quarter of the window.",
        SettingsField.LlmMaxTurns => "How many user turns the model sees before the oldest drop off (1–500). `auto` keeps them all while auto compact can run (a known context window and a share above 0), and 24 otherwise.",
        SettingsField.LlmToolCompactType => "What happens when one turn's tool calls fill the context window up to the *LLM auto compact (%)* share: `compact`, `prune`, `stop` or `off`. `compact` prunes first; if the context is still over the share, it summarizes the turns before this one, then if needed this turn's earlier tool calls into a progress note (always a summary, whatever *LLM compact mode* says). `prune` stubs this turn's older results and long call arguments, and a plan's earlier revisions and the reads of its file, and carries on. `stop` ends the turn with a notice. `off` checks nothing: the server's own limit answers.",
        SettingsField.LlmPictureKeep => "The most pictures one request carries, an attached PDF counting as one (0–500; 0 = no cap). Past it, the oldest pictures leave the conversation until half the cap is left; each becomes a line naming its file, which `view_image` can show again, and a PDF leaves its text. The newest message's pictures always stay. Every picture is sent again with every request, so a long picture session can outgrow what a server takes in one request.",
        SettingsField.LlmPictureMegabytes => "The most megabytes of pictures and attached PDFs one request carries, as sent (0–1000; 0 = no cap); a PDF's size counts where the server takes PDFs (the Anthropic and OpenAI APIs), its text's elsewhere. Past it, the oldest leave until half the figure is left, as with *LLM max images*. It also caps what one message may attach, its pictures and PDFs together. If a server still drops a request with pictures as it is sent, the app takes out half of them and tries once more.",
        SettingsField.LlmOfferTools => "Whether the model gets any tools at all. Turn it off for chat templates with no tool role. Changing it starts a new conversation.",
        SettingsField.LlmMaxToolIterations => "How many tool round trips one message may make before the turn stops (1–10000).",
        SettingsField.PlanGapPasses => "How many passes plan mode's *Close gaps…* review may run before the plan goes back to the approval pane with gaps still reported (0–100 passes; 0 = no cap). Esc stops a review at any pass. Headless has no Esc, so 0 means 100 there. A count on `/plan gaps` overrides it for that run. A pass with no gaps cut short at the limit, before *Plan gap clean passes* confirmed it, brings the pane back too.",
        SettingsField.PlanGapCleanPasses => "How many passes in a row must find no gaps before plan mode's *Close gaps…* review ends (1–5; 1 = the first pass with none). A pass after a clean one is told to look again where no earlier pass did; every pass counts toward *Plan gap max passes*, and a pass limit below it lowers it to the limit for that review. `/plan gaps confirm` needs at least 2.",
        SettingsField.PlanGapAskUser => "Whether a pass of plan mode's *Close gaps…* review may stop to ask you (`ask_user`), take a photo (`camera_capture`) or capture the screen (`screen_capture`). Off, a pass is offered none of the three, whatever the camera and screen settings say, during a pass only. Off, or where `ask_user` isn't offered (headless, *Ask user* off, or off on `/tools`: the camera and the screen stay), a decision only you can make goes into the plan's `## Risks` as an open question, which is not a gap. Read every turn, so it applies from the next pass. On by default.",
        SettingsField.PlanGapStopTone => "The tone plan mode's *Close gaps…* review ends with, so a review left to run is heard to stop: `silent`, `chime`, `bell`, `beep` or `alarm`. A converged review rings as its approval pane opens; a limit, a stall or a failed pass rings at the stop; never for a stop you caused (Esc, the page's Stop, a typed line). The picker plays the highlighted tone. On this PC only. `silent` by default.",
        SettingsField.RalphLoopReviewer => "Who checks a Ralph loop's step once its check command passes: `off` (the checks alone), `model` (one request to the chat's model, no conversation), `advisor` (the first advisor, its thread untouched) or `any` (an advisor when one is offered, else the model). A failed review unticks the step and tells the next pass why; an unclear one leaves it standing, unchecked. `any` by default.",
        SettingsField.RalphLoopCheckpoint => "How often a Ralph loop stops for your look: 0 never (the default: no regular pauses, though a `By hand:` step still waits for your check), 1 after every step that stands, N after every N. The checkpoint offers Keep, Redo with a note…, View the changes and Stop, on this PC and the Web UI page at once, and waits until answered. While it is 0, a pass may not ask you anything, and a reviewer's `needs_user` leaves its step standing unchecked (0–20).",
        SettingsField.RalphLoopPasses => "The most passes a Ralph loop runs: 0, the default, is three a remaining step (a split adds three a new step); a number is that many. One pass more is kept for fixing a failed final check. A count on `/plan ralph` or `/plan approve --ralph` overrides it for that run (0–200).",
        SettingsField.RalphLoopPassesPerStep => "The most passes one step of a Ralph loop may take before the loop stops on it, its edits left in place; two failed checks in a row stop it sooner (1–20, 4 by default).",
        SettingsField.RalphLoopCheckTimeoutSeconds => "How long a Ralph loop's check command (the plan's `verify:` after each step, its `final:` at the end, and the baseline before) may run before it is stopped and counts as failed (30–3600 seconds, 600 by default).",
        SettingsField.RalphLoopTokenBudget => "A spending brake on a Ralph loop: the most tokens one run may use, its passes and its reviews together, checked before each pass; 0, the default, is none. Counted from each start or resume.",
        SettingsField.RalphLoopStopTone => "The tone a Ralph loop ends with, also rung when a step waits for your check by hand: `silent`, `chime`, `bell`, `beep` or `alarm`; never for a stop you caused (Esc, the page's Stop, a typed line). The picker plays the highlighted tone. On this PC only. `silent` by default.",
        SettingsField.CodeAuditPasses => "How many passes a `/code-audit` may run before its done pane comes back (0–100 passes; 0 = no cap). Esc stops an audit at any pass. Headless has no Esc, so 0 means 100 there. A count on `/code-audit` overrides it for that run.",
        SettingsField.CodeAuditCleanPasses => "How many passes in a row must find nothing new before a code audit ends (1–5). A confirming pass looks first at the files no pass has read, with a focus of its own. `/code-audit confirm` needs at least 2.",
        SettingsField.CodeAuditAskUser => "Whether a code audit's pass may stop to ask you (`ask_user`), take a photo or capture the screen. Off, a pass is offered none of the three; off, or where `ask_user` isn't offered, a question only you can answer goes in the report's Open questions. Read every turn. On by default.",
        SettingsField.CodeAuditFocus => "The dimensions a `/code-audit` with none named covers: security, correctness, performance, maintainability and tests. At least one stays ticked; a focus word on the line overrides it for that run.",
        SettingsField.CodeAuditWebResearch => "Whether a code audit's passes get `web_search`, `web_fetch` and `web_links`. Off by default, because audited code may carry instructions that would send code out; off, an advisor asked in a pass gets none either. Read every turn.",
        SettingsField.CodeAuditPassToolCalls => "The tool calls a code audit's pass is asked to report within (0–500; 0 = no budget, report as you go). It is guidance, never a cut-off: coverage carries what a pass left to the next one. A lower *LLM max tool iterations* is named instead. Read every turn.",
        SettingsField.CodeAuditStopTone => "The tone a `/code-audit` ends with, so an audit left to run is heard to stop: `silent`, `chime`, `bell`, `beep` or `alarm`. It rings for a converged audit, a limit, a stall or a failed pass; never for a stop you caused (Esc, the page's Stop, a typed line). The picker plays the highlighted tone. On this PC only. `silent` by default.",
        SettingsField.ImageThumbnailSize => "The size of the transcript's picture thumbnails: `tiny`, `small`, `medium`, `large`, `xlarge` or `fullsize`. In columns × rows: `tiny` 32×8, `small` 48×12, `medium` 64×16, `large` 80×20, `xlarge` 96×24; `fullsize` draws each picture as large as the transcript allows, stacked.",
        SettingsField.FileTreeMaxLength => "How many entries `/tree` prints before it stops (1–10000).",
        SettingsField.FileTreeShowSizes => "`/tree` shows each file's size.",
        SettingsField.LlmUseFunVerbs => "The thinking spinner shows a random verb instead of `thinking` / `writing`.",
        SettingsField.LlmScanMode => "Where the app looks for a server while *LLM URL* is blank: `local`, `lan`, `both` or `off`. `local`: the usual ports on this machine. `lan`: the same ports across the local network. `both`: this machine, then the network. `off`: no scan; set the URL by hand, or pick the embedded model or a cloud API in `/server`.",
        SettingsField.WebTools => "Offers `web_search`, `web_fetch`, `open_url`, `web_links`, `web_save_link` and `download_file`. `web_links` and `web_save_link` read and change the profile's saved links, the ones `/browser list` shows. Its page's title row steps *Web browser mode* (`m`) and, where there is a Browser window (Windows, a Mac on macOS 14 or later), opens it on its home page (`o`).",
        SettingsField.WebBrowserMode => "How pages are fetched: `auto`, `http` or `browser`. `auto` uses the HTTP client and falls back to a headless browser when a page is blocked or empty; `http` never falls back; `browser` uses the browser for every page, but fetches a PDF over HTTP (headless Chromium would only download it). The buttons at the top of the *Web tools* on/off page (`a`, `h`, `b`; the toolbar's 🌐 opens it) switch it too.",
        SettingsField.WebBrowserPath => "The Chromium-based browser used for headless fetches and for making, reading and editing PDFs (`convert_to_pdf`, `/pdf`, `read_pdf`, `pdf_edit`). Empty finds Edge, Chrome or Brave in their standard folders.",
        SettingsField.WebBrowserBotcheckWindow => "What a bot check the web tools cannot get past (a Cloudflare click, a captcha) does: `ask`, `automatic` or `off`. `ask` asks you first (at the PC and on a connected Web UI page), then opens the page in the Browser window for you to solve, which the Web UI's card can show and drive (*Web UI bot check control*); `automatic` opens it without asking; `off` never does, and the tool reports the refusal. Once the check clears, the window closes and the page and its cookies go back to the tool (`web_fetch`, `web_search`, `download_file` or `convert_to_pdf`). Windows, and a Mac on macOS 14 or later. Not headless.",
        SettingsField.WebBrowserNetworkMode => "Where a fetch may reach: `internet` (public addresses only), `lan` (this machine and the local network only, its adapters' prefixes included) or `both`.",
        SettingsField.WebBrowserHomePage => "Where the Browser window's home button and a bare `/browser` go: a web address (`example.com`, `localhost:3000`), or empty for the blank page.",
        SettingsField.BrowserPrivacy => "Whether the Browser window keeps the pages it visited: `keep-history` keeps them, in its history menu (🕘, Ctrl+H; ⌘Y on a Mac) too; `clear-history` clears them when the window closes, and a list saved under `keep-history` goes at that close. Cookies and sign-ins stay either way; `/browser clear all` removes those. Each profile has its own.",
        SettingsField.WebOpenLinksIn => "Where a link the model opens with `open_url` goes: `default-browser` or `browser-window`. `browser-window` opens it in the app's Browser window, one page at a time; with no window to open (headless, macOS before 14, no WebView2 runtime, a bot check waiting in it) the link goes to your default browser. Other links the app opens always use your default browser.",
        SettingsField.WebSearxngUrl => "A SearXNG instance's base URL, used while *Web search method* is `searxng`.",
        SettingsField.WebSearchMaxResults => "How many hits a search returns (1–20).",
        SettingsField.TtsVoicePreview => "The voice pickers (and the preset picker) speak the highlighted voice as you move through them.",
        SettingsField.FileTools => "Offers the sandboxed file tools (read, write, patch, search, move, copy, zip, read_pdf, convert_to_pdf, pdf_edit…), which reach only files under the working directory; the picture tools are *Image tools*. The top of its on/off page (`/tools files`, the toolbar's 📁) has a **browser** (`b`) button that opens *File browser/tree mode*; Esc there comes back.",
        SettingsField.ImageTools => "Offers the picture tools `view_image`, `image_info`, `image_edit` and `set_splash_image`, whether *File tools* is on or not. `view_image` lets the model look at pictures; `image_info` reads size, format and metadata; `image_edit` crops, resizes, turns, flips, recolors, blurs, borders, converts, shrinks or strips metadata; `set_splash_image` adds a picture to the splash. They reach pictures under the working directory and the profile's `images` folder. The top of its on/off page (`/tools image`, the toolbar's 🌄) has an **edit mode** (`e`) button that opens *Image edit mode*; Esc there comes back.",
        SettingsField.WebBrowserSignInMode => "How `/webui browser` and a double-click on `/webui`'s link or QR code sign your default browser in to the Web UI: `one-time-link` opens a link good once for a minute, so the browser's history keeps no token; `url-with-token` opens the usual sign-in link, which the history and the browser's launch may keep. The app's own Browser window uses the usual link, or a one-time link while *Web browser privacy* is `keep-history`. `one-time-link` by default.",
        SettingsField.FileDeletesToRecycleBin => "Sends what the `delete` tool and the picture viewer's, thumbnail browser's, picture menu's and Web UI's deletes remove to the Recycle bin, where it can be restored. Off, they delete directly. A network share or a removable drive has no Recycle bin, so a delete there is direct either way; something too big for the bin is deleted for good, as Windows does. The purges (`/comfy`, `/camera`, `/screen`, `/splash` and `/pasted purge`) follow it too, their question saying which way it goes (for good on a drive with no bin). A command's or script's own deletes are the shell's, never this setting's. On by default.",
        SettingsField.TimerTools => "Offers the model the timer tools: `start_timer`, `stop_timer` and `list_timers`. Off, it has none and its prompt drops the timer sentence; `/timer` and the timers already running keep working. On by default.",
        SettingsField.ClockTools => "Offers the model the clock tools: `get_current_time`, `shift_date` and `date_difference`. Off, it has none, its prompt drops the clock sentence and a conversation no longer opens with the time. On by default.",
        SettingsField.HelpTools => "Offers the model `neon_help`, the app's own manual. Off, it has none, its prompt drops the manual's sentence and `/help <words>` shows the manual's own answer. On by default.",
        SettingsField.TimerTone => "The tone a timer rings with when it goes off: `silent`, `chime`, `bell`, `beep` or `alarm`. It rings again at each repeat until you silence or stop the timer, mid-reply too, for `/timer`'s countdowns and the model's alike, even with *Timer tools* off; a stopwatch never rings. The picker plays the highlighted tone. On this PC only. `silent` by default.",
        SettingsField.ShoppingTools => "Offers the shopping list's tools, for the list itself and for the stores' layouts. The list: `shopping_list`, `shopping_add`, `shopping_check`, `shopping_remove` and `shopping_clear` (the whole list only after your yes). The layouts: `shopping_locate`, `shopping_place`, `shopping_stores`, `shopping_layout`, `shopping_recent` and `shopping_reference` (a store's reference documents: PDFs, text files, pictures). Everything lives in the profile's `db\\shopping\\shopping.db`, each store's documents in `db\\shopping\\reference\\<store>`. `/tools shopping` opens this switch; the toolbar's 🛒 opens the list itself (`/shopping`).",
        SettingsField.ShoppingList => "Enter opens the shopping list's checklist, as `/shopping` and the toolbar's 🛒 do. There Enter or Space ticks an item, `i` adds items (typed, or from the recently bought), `p` places one at an aisle, `+` and `-` change its quantity, `n` renames it, `r` removes it, `a` ticks every item, `c` clears the ticked ones and `s` opens *Shopping stores*. Esc comes back here.",
        SettingsField.ShoppingStores => "Enter opens the stores' manager, as the `/shopping` pane's `⇄ store` does. Its first row adds a store (and makes its reference folder); Enter on a store makes it the store the list is ordered for. Its buttons: `l` its layout (aisles and walk order, sections, placement facts and the model's guesses to review, each changed with Enter), `n` rename (its folder follows), `r` remove after a yes (its layout goes, its documents stay), `f` open its reference folder and `i` read its documents again.",
        SettingsField.WebSearchMethod => "`duckduckgo` (built in, no setup) or `searxng` (the instance in *Web SearXNG URL*).",
        SettingsField.AskUser => "Offers `ask_user`, which lets the model ask you multiple-choice questions. `/tools ask` and the toolbar's 🙋 open its on/off page.",
        SettingsField.AskMaxQuestions => "How many questions one call may ask (1–10).",
        SettingsField.AskMaxChoices => "How many options one question may offer (2–15).",
        SettingsField.TtsSource => "`in-process` runs the Kokoro voice model inside the app (downloaded on first use); `http` uses a Kokoro-FastAPI server at *TTS HTTP URL*.",
        SettingsField.SttVoskModel => "The Vosk model that listens for the wake word and interrupt: `vosk-model-small-en-us-0.15`, `vosk-model-en-us-0.22-lgraph` or `vosk-model-small-en-in-0.4`.",
        SettingsField.FileMentionFolderMode => "What picking a folder from the `@` list does: `remain` keeps the list open inside it; `apply` writes `@folder/` and closes.",
        SettingsField.GlobalSkills => "Reads the global skills, the home folder's `skills` folder that every profile shares. Off, this profile sees and writes only its own skills. Needs *Agent skills*.",
        SettingsField.AgentSkills => "Lists the skills in the prompt and offers `load_skill` and `skill_editor`. Off also turns off *Project file*.",
        SettingsField.ExternalSkills => "Also reads the skills in `%USERPROFILE%\\.agents\\skills`, read-only.",
        SettingsField.SkillCompactMode => "`protected` keeps a loaded skill's instructions through a prune; `unprotected` prunes them like any tool result.",
        SettingsField.TranscriptMarkdown => "Renders replies as Markdown instead of plain text. Code fences in C#, JavaScript/TypeScript, Python, Bash, PowerShell, JSON, YAML, TOML/INI, SQL, C/C++, Java, Kotlin, Go, Rust, CSS, XML/HTML and diff are syntax-highlighted.",
        SettingsField.PastePreviewLines => "How many lines of a long paste show dimmed under its `[Pasted text #n]` placeholder (0–200; 0 = placeholder only).",
        SettingsField.SkillHashMention => "Typing `#` and part of a name on the input line lists the loaded skills; a pick writes `#name` as text.",
        SettingsField.ReflectionAutoLearn => "Lets the app learn from your work: after enough tool calls, or a tool error the model recovered from, a background reflection writes or improves a skill.",
        SettingsField.ReflectionReasoning => "The reasoning effort for the reflection alone: `none`, `low`, `medium`, `high`, `xhigh`, or `profile` for the profile's own level.",
        SettingsField.ReflectionWindow => "How many of the last turns a reflection reads (1–5; the last in full, the earlier ones trimmed).",
        SettingsField.ReflectionMinToolCalls => "How many of the model's own tool calls, counted since the last reflection, make a task worth a skill (3–20).",
        SettingsField.ReflectionMaxRequests => "How many model requests one reflection may spend before it gives up (1–20).",
        SettingsField.HideExitAutocomplete => "Shows `/exit` in the `/` list. Off, it is left out, so a stray pick cannot close the app; typing it in full still works.",
        SettingsField.EmojiPicker => "Shows a dim ☺ at the right end of the input row; a click opens the emoji picker and puts the emoji picked at the cursor. The picker is the avatar picker's grid: Recent, the categories, a search as you type, skin tones. Ctrl+J opens it too (not on a Mac), whether the ☺ shows or not. Only at the idle line, not while a reply runs.",
        SettingsField.CommandTypoIntercept => "A command name without its slash (`clear`) or with extra slashes (`//profile work`) asks *Did you mean /clear?* before sending it as text. A bare `//` is still `/settings`.",
        SettingsField.WelcomeSplash => "Shows a picture or a robot under the banner at startup until you send the first line: `image`, `robot` or `off`. `image`: one picture; ←/→ step through the set, and pictures in the profile's `images\\splash\\` folder replace the built-in ones (`/splash view` opens the folder). `robot`: a robot that stands just above the draft line, follows the mouse and your typing, and goes when you send your first line; just its head when the window is short. `/splash` shows the splash whatever the setting.",
        SettingsField.ShowHeader => "Shows the banner (the title, the version and the rule under it) at startup and after `/clear`, `/splash`, `/theme` and a profile switch. Off, the screen starts with the transcript. `/new` keeps its own rule either way. `/header` flips it; the change shows at the next clear.",
        SettingsField.ShowWorkingDirectory => "Prints the working directory at the right of the banner's title line.",
        SettingsField.QueueMode => "How messages meet the queue (`/queue`): `automatic`, `manual` or `off`. `automatic`: a message sent while a reply streams is listed (a count, and in `/queue`) and sent when the reply ends. `manual`: every typed message is queued, at the idle line too, and goes only when you press `➤ send` (`s`) on `/queue`, one per press; commands and spoken requests are never queued. `off`: no queue; a line sent during a reply still goes when it ends, unlisted, and `/queue` leaves the `/` list. `/queue mode <word>` sets it too.",
        SettingsField.QueueCancelMode => "What a canceled reply does with the queue: `hold` keeps it until your next message, `drain` sends the next message at once, `empty` drops them all. Under *Queue mode* `manual` nothing is sent by itself either way; `empty` still drops them. `/queue cancel <word>` sets it too. Under `hold` a message from the Web UI counts as your next message too, and the page's Resume sends what was held.",
        SettingsField.SessionLogging => "Writes every completed turn to the profile's `sessions.db`, so `/sessions` can list, search and restore it.",
        SettingsField.SessionRetentionDays => "Sessions whose last turn is older than this are deleted at startup (0–3650; 0 = keep forever).",
        SettingsField.SessionNamingMode => "How a session gets its title: `model-written` asks the model for a short name after the first turn; `first-line` uses the first line you sent.",
        SettingsField.SessionShowName => "Which titles show on the line above the input row: `all`, `model-written` (only a name the model wrote or you typed) or `none`.",
        SettingsField.SessionTool => "Offers the model `session_manager`, to search, list and read this profile's earlier sessions (never to restore or purge them).",
        SettingsField.SessionSearchMaxResults => "How many sessions a `session_manager` search or list returns (1–20).",
        SettingsField.ToolsDollarMention => "Typing `$` and part of a name on the input line lists the tools the next turn offers; a pick writes `$name` as text.",
        SettingsField.ReflectionCooldownMinutes => "How long an automatic reflection waits after a reflection wrote a skill (0–1440; 0 = off). Turns that loaded that skill and hit an error after loading it never wait: a fresh skill that failed is worth fixing at once.",
        SettingsField.ReflectionIncludesSessions => "The reflection starts with the earlier sessions that match the turn, and can search them.",
        SettingsField.ReflectionMode => "What a reflection may write: `create-update` a new skill or an improvement to one that exists; `update-only` only an improvement, never a new skill. An improvement covers a skill's supporting files too under *Reflection edit supporting files*. Under `update-only` with no skill to update, no reflection runs and `/learn` says so, and *Reflection confirm mode* `new` never asks.",
        SettingsField.ReflectionConfirmMode => "Whether a reflection asks before it writes: `none` never; `all` before a new skill and before an edit; `new` before a new skill only; `edit` before an edit (an update or a supporting file) only. The ask is a Keep / View / Discard pane at the idle line while the reflection waits; Esc discards. With the Web UI on, the page asks at once too, with the summary, Keep, Discard and the proposal under View; the first answer wins.",
        SettingsField.ReflectionCooldownMode => "`last-written-skill` makes only a turn that used the skill just written wait; `all-skills` makes every automatic reflection wait.",
        SettingsField.DraftEditor => "The program `/draft` opens its temporary file with (`code --wait`, `notepad`…); it must wait until the file is closed. Empty uses the app Windows opens `.txt` files with.",
        SettingsField.FileViewImageMaxPerCall => "How many pictures one `view_image` call may load, and how many pages one `read_pdf` call with pictures draws (1–100).",
        SettingsField.McpServers => "The master switch: on, every enabled server starts at launch (and after a profile switch) and its tools are offered; off, nothing starts.",
        SettingsField.McpConnectTimeoutSeconds => "How long a server gets to finish the handshake and list its tools before it is marked failed (5–300).",
        SettingsField.GitLibTools => "Offers the GitLib tools (`gitlib_status`, …: status, log, show, diff, blame, branch, stage, commit, stash, discard, delete) over the repository in the working directory. They run inside the app, with no git program. Off, the model reaches git through the shell only, and `/gituser` does nothing.",
        SettingsField.GitLibDiffMaxLines => "Where a `gitlib_diff` patch is cut (20–5000).",
        SettingsField.GitLibLogMaxCommits => "How many commits `gitlib_log` returns unless the call says otherwise (1–200).",
        SettingsField.ShellCommandPolicy => "Whether and how the model may run shell commands through `run_command`: `off`, `ask` or `yolo`. `off`: no shell tools are offered. `ask`: a command not on *Shell allowed commands* goes to the approval pane first (with no pane, it is refused). `yolo`: everything runs and nothing is asked. `--yolo` sets `yolo` for one launch.",
        SettingsField.ShellCommandAllowed => "The command prefixes allowed for good (`git status`, `dotnet build`, `python`). Enter on one removes it after a yes; the pane's *Allow … always* adds one. The list's policy button (`p`) steps *Shell command policy* from off to ask to yolo, yolo after a yes (a no goes on to off). `/tools shell allowed` opens the list; `/profile push allowed` copies it to another profile.",
        SettingsField.ShellDefault => "The shell `run_command` uses when the call gives no `shell`: `powershell` (pwsh when installed, else Windows PowerShell 5.1), `cmd`, or `bash` (Git Bash, when found). On macOS: `zsh` (the default there), `bash` or `powershell` (pwsh, when installed).",
        SettingsField.ShellTimeoutSeconds => "How long a foreground command without its own `timeout` may run before it is killed (1–3600).",
        SettingsField.ShellForegroundCapSeconds => "The longest a foreground command may run, whatever its `timeout` says (10–3600).",
        SettingsField.ShellOutputMaxChars => "The most output one result carries back (2000–500000). Past that, the start and end are kept, and the whole text goes to `.neon\\shell\\<id>.log` under the working directory, where `read_file` can reach it.",
        SettingsField.ShellCodeLanguages => "The languages `execute_code` may run: `powershell`, `python`, `node`. One or more; a language is offered only while its interpreter is found. Enter or Space turns one on or off, and `a` turns all on. The last one on stays on, so `n` is refused.",
        SettingsField.ShellCodeTimeoutSeconds => "How long an `execute_code` script without its own `timeout` may run before it is killed (1–3600).",
        SettingsField.ShellCodeMaxToolCalls => "How many tool calls one script may make through the bridge (1–500).",
        SettingsField.LlmCompactShowSummary => "After a compact, shows what it did: the summary as dim lines, or one line per pruned tool result, then how many messages were kept at the start and end.",
        SettingsField.GitLibEmail => "The `user.email` that `/gituser` writes into the repository's config. The GitLib tools never read it.",
        SettingsField.GitLibName => "The `user.name` that `/gituser` writes beside it.",
        SettingsField.ShellToolBridge => "Lets an `execute_code` script call the app's other tools through its `neon_tools` module (a loopback socket with a per-run token). Off, no module is written and nothing mentions it, so the script does everything itself.",
        SettingsField.FileBrowserMode => "What the folder browsers (`/cwd browse`, the *Obsidian vault* row), `/tree` and `/browse` list. `hide-hidden` hides hidden and system entries and dot-folders (and, in `/tree` and `/browse`, dot-files). `show-hidden` lists them too, except that `/tree` and `/browse` always leave out `.git` folders.",
        SettingsField.StatusBarItems => "Which sections the Status bar under the input line shows, and in what order. A checklist of **Status** (the switch and job icons: 🔊 🎤 👂 ✋, 🧠, 🏷️…), **Spinner** (the busy row's spinner, label and clock, then `Esc to stop`; always on, but it moves like the others), **Queued**, **Timers** (a double-click asks to cancel them all), **Reading** (`/read` or `/echo` while it reads), **Usage** (the context and the token tally), **Model** (the model's name and reasoning mark) and **Working directory** (the path as the tool bar shows it). Enter or Space flips one; Delete unchecks it; `a` / `n` / `d` pick all, none or the default (which puts the order and sides back too). The checklist has two groups, *Pinned left* and *Pinned right*: Shift+←/→ (or Alt+←/→) moves the section under the cursor to the other side, Shift+↑↓ (or Alt+↑↓) moves it a place (crossing into the other group at its edge) and Shift+Home/End to its group's top or bottom. The left group starts the row and the right group ends it; under a reply the busy row follows the same sides. On a narrow row the model's name and the working directory shrink and then go first, then the right group gives way, then the left. A double-click or a right-click on the row's blank space opens `/settings`. The row reads `default`, `all`, `none` or the left group's sections, `|`, then the right group's.",
        SettingsField.HintsBar => "Whether the keys' hints get a bar of their own over the Status bar. The bar shows one hint at a time, the first of: the kill switch's warning, a waiting second press (Ctrl+C to exit, a rewind, a splash picture's delete), an open pane's keys, then the arrows' keys over the splash or the pictures and `/read`'s keys. **auto** gives it a row while there is a hint and keeps the row, blank, until the next send, the end of a reply, a pane opening or closing, a resize, or 10 seconds with no hint and no key, so typing never moves the input line. **always** keeps the row. **off** puts the hints back on the Status bar. A double-click on the bar opens `/settings`; it moves with the other bars under *Toolbar order*.",
        SettingsField.ToolbarItems => "Which items the toolbar shows, and in what order. A checklist (`/toolbar edit` opens it too) of every icon (🪪 Profile, 🧮 Themes, the tool switches from 🐚 Shell to 🖨️ Print, 📄 Log, ⚡ Process, 🎞️ and 🪟 the ComfyUI viewers, 📺 YouTube, ⭐ Saved links…), the working-directory path and **Model name** (the model's name and reasoning mark). Enter or Space flips one; Delete unchecks it; `a` / `n` / `d` pick all, none or the default (which puts the order, sides and dividers back too); none hides the row. The checklist has two groups, *Pinned left* and *Pinned right*: Shift+←/→ (or Alt+←/→) moves the item under the cursor to the other side, Shift+↑↓ (or Alt+↑↓) moves it a place (crossing into the other group at its edge) and Shift+Home/End to its group's top or bottom. `+` (*+ divider*) puts a dim │ after the item under the cursor; it moves like an item, Delete takes it out, and it shows only between two drawn items of its side. On a narrow row the model's name and the path shrink and then go first, then the right group gives way, then the left; what gives way simply goes. On the bar a double-click on an item runs it, and so does a right-click on an icon; a double-click or a right-click on its blank space opens `/settings`. A tool switch opens its on/off page and sits on a dark background while it is off. The row reads `all`, `off` or how many are checked.",
        SettingsField.ShellPolice => "Refuses a shell command, script or background-process input that names a path outside the working directory, or `.git`, `.neon`, the project file or the app's folder, before it runs or the pane asks. Turning it off asks first, and also stops *Shell police forbidden strings* and the database rules: while *SQLite tools* is on, anything that reaches SQLite is refused, and while *SQL tools*, *Oracle tools*, *MySQL tools* or *PostgreSQL tools* is on, anything that reaches that family (its clients and drivers, such as sqlcmd, sqlplus, mysql or psql, or a host its connections name). `/tools shell police` opens this row; `--no-police` turns it off for one launch.",
        SettingsField.ShellPoliceForbiddenStrings => "Strings the shell police refuses outright: a command, script or background-process input containing one is not run, even under `yolo`. Case is ignored and any run of spaces, tabs or line breaks counts as one space (`rm -rf` also catches `RM   -RF`). Enforced only while *Shell police* is on. The model is told the command was refused, not which string; the 👮 line names it for you. The top row adds a string; Enter on one removes it after a yes; ↺ restore defaults (`r`) puts the starter list of harmful actions back, after a yes. The police page's strings button (`s`) opens the list too. The whole text is read, so searching for a listed string, or a script that mentions one, is refused too. A tripwire, not a sandbox: text built in pieces gets past it. `/profile push policestrings` copies the list to another profile.",
        SettingsField.ToolCollapseCount => "A run of more tool calls than this folds under one summary line, `▸ 🛠️ 7 tool calls — read_file ×3, …` (0–100; 0 = never fold). A call and its result count as one. While the run goes on only its last calls show, and only the summary afterwards.",
        SettingsField.CodeCollapseCount => "A top-level code block longer than this folds to its label, `▸ 📜 csharp · 57 lines`, once its closing fence arrives (0–100; 0 = never fold). While it streams, only its last this-many lines show. Needs *Transcript markdown*.",
        SettingsField.ShowFileDiffs => "A file edit (`patch_file`, `write_file`, `unc_patch`, `unc_write`) shows its diff under its line. The diff opens with `└ Added 3 lines, removed 1 line`, then the changed lines, numbered, with three of context: added ones on a green background, removed ones on a red one, colored by the file's language. It folds with the tool run. Off, the line alone. The model's result is the same either way.",
        SettingsField.DiffMaxLines => "The most rows of an edit's diff shown; past it `… 12 more lines` ends it (0–500; 0 = the header line alone).",
        SettingsField.DiffCollapseCount => "An edit's diff of more rows than this folds once its tool run is over (0–500; 0 = never fold). It shows open while the run goes on, then folds to `▸ Added 3 lines, removed 1 line · 14 rows`; the rows are counted over the whole diff, past *Diff max lines* too.",
        SettingsField.ObsidianTools => "Offers the vault tools (search, list, read, links, daily, write, properties, move) over the vault in *Obsidian vault*, once one is set. The top of its on/off page (`/tools obsidian`, the toolbar's 💎) has a **vault** button (`v`) that opens *Obsidian vault*'s folder picker; Esc there comes back.",
        SettingsField.ObsidianVault => "The vault's folder (the one holding `.obsidian`), separate from the working directory. Enter opens the `/cwd browse` folder picker.",
        SettingsField.ObsidianAllowDelete => "Offers `vault_delete`, which moves a note or attachment where the vault's Deleted files setting says: the system's bin or the vault's `.trash` (never deleted for good).",
        SettingsField.SqlTools => "Offers the SQL tools (connections, tables, columns, describe, relationships, indexes, query) over the connections in `sql.json`, once one is defined. Each connection reaches its own database alone: a statement naming another, or the server's own catalog (`sys.databases`, `sys.dm_*`), is refused, and another database needs a connection of its own. The top of its on/off page (`/tools sql`, the toolbar's 🛢️) has an **offered** button (`o`) that shows how many are offered and opens *SQL connections offered*.",
        SettingsField.SqlMode => "Whether the SQL Server tools may change data: `read-only` or `read-write`. `read-only`: the SQL tools only read. `read-write`: `sql_execute` is offered too, on the connections whose entry in sql.json says `\"access\": \"readwrite\"` (the default is `read`; the wizard asks) — one statement per call of the kinds *SQL statements allowed* ticks, committed as it runs. Each change asks first: Deny, Allow once, or Allow for this session (that connection, until the session ends); a read asks nothing and runs read-only. BEGIN TRAN/COMMIT, SET, USE, GRANT/DENY/REVOKE, logins, users and roles, DBCC, BACKUP/RESTORE, BULK INSERT, OPENROWSET and the other doors out, linked servers, xp_ and sp_configure, dynamic SQL (EXEC of a string, sp_executesql) and CREATE or DROP of a database stay refused. Never offered headless or in plan mode; every change is written to the log.",
        SettingsField.SqlStatementsAllowed => "Under *SQL mode* `read-write`: the kinds of statement `sql_execute` may run, ticked on a checklist. The kinds: changing data (INSERT, UPDATE, MERGE), deleting (DELETE, TRUNCATE TABLE, a MERGE that deletes), creating (CREATE TABLE, INDEX, VIEW, SEQUENCE, TYPE, SCHEMA, SYNONYM), changing structure (ALTER TABLE, INDEX, VIEW, SEQUENCE, SCHEMA; sp_rename is a procedure), dropping (DROP …), upkeep (UPDATE STATISTICS), procedures and triggers (EXEC of a procedure, and making or changing a procedure, function or trigger, whose code runs later) and reading (SELECT). A statement needs the kind of every change in it. `a` / `n` / `d` pick all, none or the default (changing data, creating, reading). With none ticked, `sql_execute` is not offered.",
        SettingsField.SqlQueryMaxRows => "How many rows `sql_query` returns unless the call says otherwise (1–100,000). Past that, the header says more exist.",
        SettingsField.SqlQueryTimeoutSeconds => "How long one SQL tool's batch may run on the server (1–600 s).",
        SettingsField.SqlConnectionsProfile => "Enter opens this profile's `sql.json` in your editor (made with a commented example of each sign-in kind when missing). The row shows how many connections it has.",
        SettingsField.SqlConnectionsGlobal => "Enter opens the global `sql.json` (in the home folder's `configs`), which every profile reads, in your editor. On a name clash, the profile's entry wins.",
        SettingsField.SqlSetPassword => "Pick a connection that takes a password (`sql` or `runas`) and type it, masked. It is saved to that connection's store: encrypted in its `sql.json`, or in Windows Credential Manager.",
        SettingsField.SqlPercentMention => "Typing `%` and part of a name on the input line lists the connections (server, database, description); a pick writes `%name` as text.",
        SettingsField.SqlConnectionsOffered => "A checklist of the connections in both `sql.json` files. Nothing is offered until you tick it here or offer it from the add-connection wizard, and a connection added later stays hidden until you tick it. `a` / `n` tick all or none (\"all\" means the ones listed now). A hidden connection is invisible to every SQL tool, the rules, the `%`-mention and the default (`sql_connections` says how many are hidden, never which). A ticked name no longer in the files is dropped when the checklist opens, and the status line names it; not while a file cannot be read, nor a name an entry with a problem still holds.",
        SettingsField.SqlAddConnection => "A wizard for a new connection, one page per choice, or to edit a saved one. It can **test** the draft (`SELECT @@VERSION`, then the other databases the login could open) before saving it. The database is required: the connection reaches that one alone. With entries saved, its first page lists them: + New, or one to edit, which opens on its summary prefilled (Enter on a row changes it; its file kept, the stored password kept unless another is typed).",
        SettingsField.Theme => "One of the sixty built-in themes (in categories such as cinema, machines and nights) or your own from the home folder's `themes` folder. They are listed by name; a file of yours named like a built-in replaces it. `/theme` and the toolbar's 🧮 open the same picker.",
        SettingsField.ComfyTools => "Offers `generate_image`, once *ComfyUI URL* is set and a workflow is in a `comfy` folder. The top of its on/off page (`/tools comfy`, the toolbar's 🎨) has an **offered** button (`o`) that shows how many are offered and opens *ComfyUI workflows offered*.",
        SettingsField.ComfyUrl => "The ComfyUI server, often another machine on your LAN (`http://gpu-box:8188`). As with the LLM server, the web tools' network mode never blocks it.",
        SettingsField.ComfyTimeoutSeconds => "How long the tool waits for one generation, queue included (10–3600). The job may still finish in ComfyUI.",
        SettingsField.ComfyOutputFolder => "The folder under the profile's `images` folder the pictures are saved in (`comfy\\pony-txt2img-1234.png`), kept out of the working directory. Empty uses the `images` folder itself.",
        SettingsField.ComfyWorkflowsOffered => "A checklist of the installed workflows the model is offered. Nothing is offered until you tick it here or offer it from the add-workflow wizard, and a workflow added later stays hidden until you tick it. `a` / `n` tick all or none (\"all\" means the ones installed now). With one ticked, every plain request and a plain `/imagine` go to it. `/imagine <name>` can still use a hidden one. A ticked workflow no longer installed is dropped when the checklist opens (not one whose file failed to load), and the status line names it.",
        SettingsField.ComfyAddWorkflow => "A wizard that **builds** a standard workflow from your server's checkpoints, or **imports** one you exported from ComfyUI.",
        SettingsField.ImageEditor => "Where a double-clicked picture, or one the model opens with `open`, opens. Empty: the built-in picture viewer. `system`: the app Windows registers for the file type (Paint for png, jpg and bmp). Anything else is a command, with the file's path appended (`mspaint`, `\"C:\\Program Files\\GIMP 3\\bin\\gimp-3.exe\"`).",
        SettingsField.ComfyMaxPicturesPerCall => "The most pictures one `generate_image` call or `/imagine --count` makes (1–16). Each is a full job, and all of them go to the model in the next request, where a local vision server has its own limit.",
        SettingsField.ComfyReinforceNegatives => "When the model writes the prompt, it also adds a few opposite tags to the workflow's negative prompt where the image model tends to drift (a solo figure → `multiple girls`, night → `daylight`). Skipped for a verbatim prompt, a negative set for the call, `/imagine`, families without a negative (Flux, FLUX.2, Klein, Krea 2, Z-Image, Ernie Turbo, Boogu, Ideogram 4) and a workflow whose `.md` says `reinforce: false`.",
        SettingsField.ComfyShowPrompts => "Shows what was sent under each picture: the `prompt:`, the `negative:` and a `params:` line (size, steps, cfg, denoise, seed, sampler, scheduler). Off, only the picture's line shows. The model sees the same either way.",
        SettingsField.ComfyCaretMention => "Typing `^` and part of a name on the input line lists the offered workflows (family, shape, size). A pick writes `^name`, which `generate_image` reads as the workflow to use.",
        SettingsField.ComfyPictureStrip => "Keeps the session's ComfyUI pictures as thumbnails in a strip above the input line, newest at the left. With the input line empty, ←/→ highlight one and Enter opens it, even while a reply runs; a double-click opens any, and dragging one onto the input row attaches it to your message. The strip's **🎞️** opens the picture viewer on the output folder, and its **‹** / **›** step the highlight. Its **×** hides the strip (later pictures still gather in it) until the **🎞️** on the line above the input row brings it back. `/clear`, `/new` and a session switch empty it; a restored session or a `/rewind` puts its pictures back. It hides while a menu is open or the window is too short.",
        SettingsField.ReflectionYieldsToTurns => "A message sent while a reflection runs pauses it, so the reply gets the server. The same reflection runs again once the reply and any queued messages are done. Turn it off if your server handles requests in parallel.",
        SettingsField.BotChatComfy => "Gives the bots this profile's *ComfyUI workflows offered* for pictures. Off, *Botchat ComfyUI limited workflows* decides; with neither, the chat is talk alone. Of the set, the text → image workflows draw new pictures and the image → image ones rework the chat's pictures (other kinds are skipped); with several of a kind, the `automatic` prompt writer picks one by name. Needs *ComfyUI tools* on and a *ComfyUI URL*. The main chat's own `generate_image` is never among the bots' tools.",
        SettingsField.BotChatLimitedComfyWorkflows => "The ComfyUI workflows the bots get while *Botchat ComfyUI enabled* is off: tick them in the checklist (`a` / `n` for all or none), any installed workflow, offered to this chat or not. With none ticked, no pictures. A ticked workflow no longer installed is dropped when the checklist opens, as on *ComfyUI workflows offered*.",
        SettingsField.BotChatImageMode => "Who draws: `automatic` or `autonomous`. `automatic`: the app writes a prompt from each reply and draws it. `autonomous`: the bots get `generate_image` over the Botchat ComfyUI workflows and draw when they choose.",
        SettingsField.BotChatImageAsync => "On: the next bot speaks while the picture renders, and the picture appears when nothing is streaming. Off, each reply is held back until its picture is drawn, then appears under it.",
        SettingsField.BotChatLlmMode => "Whose LLM the bots use. `single`: every bot uses this profile's server, model and reasoning. `multi`: each bot uses its own profile's URL, model, API key, timeouts and reasoning (a blank URL borrows this profile's server). A bot whose server does not answer at the start sits the chat out, with a notice. Read when a chat starts or resumes.",
        SettingsField.LlmMidTurnUsage => "What the token usage on the status bar shows during a reply. `estimate`: context and tok/s update live, marked `~` (counting one token per streamed chunk), until the server's figures arrive at the end of each request. `last-known`: the figures from the last completed request.",
        SettingsField.KeepMessageHistory => "Saves the ↑/↓ history (newest 100 lines, the Web UI's sent lines among them) in the profile's `sessions.db`, so it survives restarts and profile switches. Lines holding a collapsed paste or a picture are not saved. Off, the saved lines are deleted the next time the profile loads. `/msgclear` empties it either way.",
        SettingsField.BotChatNonTtsDelaySeconds => "Seconds to pause after each reply when no voice plays (*TTS output* off), so there is time to read it (0–30; 0 = no pause). A line you send meanwhile, or one queued while the bot was replying, ends the pause and goes to the bots at once; Esc during the pause ends the chat.",
        SettingsField.ShellPreferNative => "Steers the model to the app's own tools: a single shell command one of them covers (`cat` → `read_file`, `curl` → `web_fetch`…) is sent back with the tool to use, once a turn. Sent again, it goes to the approval pane.",
        SettingsField.LlmShowThinking => "Streams a reasoning model's thinking as a dim block (its last five lines). When the answer starts, the block folds to `▸ 💭 thought for 4.2s`. Click that line, press Ctrl+O or use `/expand` to see it again. Needs *Transcript markdown*. Thinking is never spoken or logged, and only `/copy --thinking` copies it.",
        SettingsField.ClaudeCodeExecutable => "The Claude Code CLI to run. Blank looks for `claude.exe` on the PATH, then npm's `claude.cmd`, then `%USERPROFILE%\\.local\\bin\\claude.exe` (where the native installer puts it). A path you set must exist; it is never swapped for another.",
        SettingsField.ClaudeCodePermissions => "What Claude may do during a `/claude` run. `read-only`: `Read`, `Grep`, `Glob`, `WebSearch`, `WebFetch`. `read-write`: its usual tools with file edits accepted, commands denied. Nothing is ever asked: anything outside the level is denied, and the reply lists what was. Claude works in the working directory, but outside the app's sandbox, shell policy and approval pane.",
        SettingsField.ClaudeCodeModel => "The `--model` for `/claude`: Claude Code's default, `fable`, `opus`, `sonnet` or `haiku` (the latest of each), or *Other…* to type a model name.",
        SettingsField.ClaudeCodeEffort => "The `--effort` for `/claude`: Claude Code's default, `low`, `medium`, `high`, `xhigh` or `max`.",
        SettingsField.Advisors => "Offers the model `neon_advisor`, to ask one of the *Advisor list*'s profiles for advice. The advisor answers on its own profile's server and model, under its own persona and the role you gave it, and may use this chat's read-only tools (never the question pane, the camera, the screen or another advisor). `/advisor` asks one yourself, on or off. The top of its on/off page (`/tools advisors`, the toolbar's 🦉) has an **advisors** button (`a`) that opens *Advisor list*.",
        SettingsField.AdvisorList => "The advisors: other profiles, each with the role it advises in (free text, such as `database architect`), led by its profile's avatar. Enter on *+ Add an advisor…* picks a profile (not this one, not one already listed) and asks its role; Enter on an advisor changes its role or removes it. A profile that is gone shows `(missing)` and is refused. The rows, and the band while the cursor is on this row, name each advisor's kind of server (`claudecode`, `embedded`, `docker`, `anthropic`, `openai`, `http` for any other URL, or `scan` with no URL saved) and model.",
        SettingsField.AdvisorContext => "What the model's calls send. `brief`: the model's question and context. `recent`: also the last 10 messages (tool results cut to 500 characters). `/advisor` always sends them.",
        SettingsField.AdvisorCallsPerTurn => "The most advisor calls one reply may make, all advisors together (1–10). Past that, the model carries on alone.",
        SettingsField.AdvisorMaxToolIterations => "The tool round trips an advisor may make before it answers (0–10; 0 = no tools, text only). Its last round is always asked for words.",
        SettingsField.AdvisorThreadPairs => "How many earlier questions and answers each advisor remembers (1–50); the oldest go first. The threads belong to the session: `/new` and loading another session start them over, and they are saved with it.",
        SettingsField.AdvisorEmbedded => "Only for an advisor on the embedded server whose profile names another model than the one running. `parent-server`: it answers on the running model, and the answer's footer names both. `multi-server`: an extra `llama-server` for its model (more memory), kept for its later calls until *Embedded servers enabled* goes off or you quit.",
        SettingsField.AdvisorConfirm => "Each call waits for your yes (the cursor starts on No; Esc means no). A no tells the model to carry on without it. In a headless run, calls are refused.",
        SettingsField.AnthropicApi => "Offers the Anthropic API on `/server` while a key is set. If it is off (or has no key) while the Anthropic API is the saved LLM URL, the app scans for a server as if the URL were blank.",
        SettingsField.AnthropicApiKey => "Your Anthropic API key (`sk-ant-…`), saved encrypted for your Windows account and shown as `(set, encrypted)`. Typing replaces it; an empty entry clears it.",
        SettingsField.AnthropicApiMaxTokens => "The output cap per request, thinking included (1,024–128,000). A reply that hits it stops short, and the log says so.",
        SettingsField.AnthropicApiPromptCaching => "Marks the tools, system prompt and conversation for Anthropic's prompt cache. Each request then re-reads the previous one's content at a fraction of the price.",
        SettingsField.OpenAIApi => "Offers the OpenAI API on `/server` while a key is set (over the Responses API, with the reasoning shown as OpenAI's summary; every message is billed). If it is off (or has no key) while the OpenAI API is the saved LLM URL, the app scans for a server as if the URL were blank. Sampling settings are not sent to it.",
        SettingsField.OpenAIApiKey => "Your OpenAI API key (`sk-…`), saved encrypted for your Windows account and shown as `(set, encrypted)`. Typing (masked) replaces it; an empty entry clears it. It goes only to api.openai.com, never to a local server or the Anthropic API.",
        SettingsField.OpenAIApiMaxTokens => "The output cap per request, reasoning included (`max_output_tokens`): 0 sends none and the model's own limit applies, else 1,024–128,000. A reply that hits it stops short, and the log says so.",
        SettingsField.OpenAIApiOrganization => "The organization a request is billed to (the `OpenAI-Organization` header), for an account in several. Empty sends none: the key's default organization.",
        SettingsField.OpenAIApiProject => "The project a request is billed to (the `OpenAI-Project` header). Empty sends none: a project key already names its project.",
        SettingsField.BotChatSkills => "Offers every bot `load_skill` (never `skill_editor`) over the skills this chat can see. Those are the starting profile's, the global ones while *Global skills* is on and, with *External skills*, the external ones, but never a bot's own profile's. In `automatic` mode the prompt writer gets them too. Off, *Botchat limited skills* decides. Needs *Agent skills*; switching `load_skill` off in `/tools` turns this off too.",
        SettingsField.BotChatVision => "On its turn, shows each bot the newest 4 pictures since it last spoke (not the ones it drew itself), each captioned with whose it is. Only for models that read images: a text-only server fails the turn (in `multi` mode, every bot's model counts). Pictures are not kept for `/botchat --resume` or the saved session. Off, the bots see text alone: a bot is not shown the pictures of its own `generate_image`, `view_image`, `camera_capture`, `screen_capture` or `image_edit` either, and is told so, though the transcript still shows them.",
        SettingsField.ThemedExternalWindows => "The app's own windows wear the theme: a themed dark title bar (Windows 11; Windows 10 gets a plain dark one) and the theme's background and colors. They are the picture viewer, the thumbnail browser, the camera's live window, the log and process windows, the video window and the Browser window. Off, they stay black.",
        SettingsField.ThemedBackground => "The terminal's page takes the theme's background color while the app runs, and gets its own back when the app exits. Off, the terminal profile's background (a color scheme, acrylic or a picture) stays as it is.",
        SettingsField.ReflectionEditsSupportingFiles => "Lets a reflection also change a skill's supporting files (the data, examples or scripts beside its `SKILL.md`) with `skill_editor`'s `write_file` and `edit_file`. Off, a reflection writes the `SKILL.md` alone; the main chat may always write them.",
        SettingsField.BotChatImageMentionMode => "What a bot's mention of a picture it never drew does: `off` ignores it, `generate` has ComfyUI draw it for the bot. A failed `generate_image` call is drawn either way. Only under *Botchat image mode* `autonomous`.",
        SettingsField.BotChatImg2ImgMode => "Which pictures a rework may start from: the `latest` one, or any in `chat-history` (the last 8, numbered). Only while the Botchat ComfyUI workflows include an image → image one.",
        SettingsField.BotChatLimitedSkills => "The skills the bots may load while *Botchat skills enabled* is off: tick them in the checklist (`a` / `n` for all or none). With any ticked, every bot (and, in `automatic` mode, the picture prompt writer) is offered `load_skill` for those skills alone; with none, no skill tool. Needs *Agent skills*. A ticked skill not listed now (external skills off, another folder's own) is skipped, and shows after the others as *not available now*: untick it there, or `n` clears it with the rest.",
        SettingsField.BotChatLimitedTools => "The tools the bots get, ticked in a checklist from the Camera, Clock, Image, Questions, Screen, Timers, Web and YouTube groups. `a` / `n` tick all or none. A ticked tool is offered only while this chat would offer it too (its switch on, not off in `/tools`). With none ticked, no tools. A ticked tool from another group (an older list's) is dropped when the checklist opens.",
        SettingsField.BotChatMemory => "Gives every bot memories: the list in its prompt, and `save_memory` and `recall_memory`. Inside `/botchat` this alone decides, over every profile's *Memory mode* (the starting profile's too). *Botchat memory mode* says whose memories.",
        SettingsField.BotChatMemoryMode => "Whose memories the bots use: `shared-parent` (every bot the starting profile's) or `independent` (each bot uses its own profile's; the starting profile's bot uses the starting profile's).",
        SettingsField.LlmPreserveThinking => "Sends the model's thinking from earlier turns back to a local server, as `reasoning_content`, and asks the chat template to keep it. The template is asked with `chat_template_kwargs`: `preserve_thinking` for Qwen3.6, `clear_thinking: false` for GLM. The current turn's thinking is always sent back, so a model keeps its reasoning between tool calls. This costs context; a `/compact` prune drops older thinking first. The Anthropic API is not affected.",
        SettingsField.SessionSaveThinking => "Saves each reply's thinking with the session, so a resumed session can send it back when *LLM preserve thinking* is on. Leave it off to keep `sessions.db` smaller; thinking saved earlier is still read back.",
        SettingsField.LlmSampling => "Sampling overrides per model (temperature, top_p, top_k, min_p, the penalties, an extra body). The row lists the models that have some; Enter opens the `/sampling` pane.",
        SettingsField.LlmSamplingFromHuggingFace => "Shows a model's recommended sampling when the server does not report its own defaults (vLLM, SGLang, LM Studio) and the model id is a Hugging Face repo (`Qwen/Qwen3-8B`). The `/sampling` pane then reads the model card's `generation_config.json` and shows its values as `(Hugging Face)`. vLLM and SGLang use that file unless started otherwise. It makes one request to huggingface.co per model and connect, never with your API key, and is for display only.",
        SettingsField.HomeAssistantTools => "Offers the Home Assistant tools (`ha_overview`, `ha_states`, `ha_history`, `ha_lights`, `ha_scene`, `ha_media`, `ha_todo`, `ha_call_service`, `ha_assist`), once a URL and a token are set.",
        SettingsField.HomeAssistantUrl => "Your Home Assistant server (`http://localhost:8123`, or another machine on your LAN). As with the LLM server, the web tools' network mode never blocks it.",
        SettingsField.HomeAssistantToken => "A long-lived access token (in Home Assistant: your profile → Security → Long-lived access tokens). It is typed into a masked field and saved encrypted for your Windows account; empty clears it. Never written to the log.",
        SettingsField.HomeAssistantTest => "Asks the server for its version with the saved URL and token, and shows the answer.",
        SettingsField.HomeAssistantActionPolicy => "What the model may switch. `off`: it only reads. `ask`: lights, scenes, the TV's power, volume, source and playback, and to-do lists run; anything else (a remote key, a button, a switch, a script, an automation, a restart, a sentence for Assist) waits for your yes. In a headless run, those calls are refused. `allow`: everything runs. `/ha` never asks.",
        SettingsField.HomeAssistantAssistAgent => "The conversation agent `ha_assist` and `/ha say` talk to (such as `conversation.google_generative_ai`). Empty uses Home Assistant's default.",
        SettingsField.HomeAssistantTimeoutSeconds => "How long one request may take (2–60 s).",
        SettingsField.YouTubeTools => "Offers the YouTube tools: search, playback where *YouTube open links in* says, and the profile's saved videos. `youtube_search` and `youtube_playlist` need a *YouTube API key*; `youtube_play`, `youtube_control` and `youtube_status` play a video or a public playlist where *YouTube open links in* says (the video window needs Windows, with the WebView2 Runtime Windows 11 has, or macOS 14 or later); `youtube_saved` and `youtube_save` keep videos, each resuming where it was left. Playing by a video's or playlist's id or link needs no key. A headless run offers the search, the playlist listing and the saved videos. `/youtube` works either way. The top of its on/off page has **max** (`m`), **voice** (`v`), **order** (`o`) and **safe** (`s`) buttons that open *YouTube search max results*, *YouTube while speaking*, *YouTube search order* and *YouTube safe search*; Esc there comes back.",
        SettingsField.YouTubeApiKey => "Your YouTube Data API v3 key, for searching. Make one in the Google Cloud Console: create a project, enable YouTube Data API v3 (APIs & Services › Library), create an API key under Credentials and restrict it to that API, with no application restriction. A search costs 100 of the project's 10,000 free units a day (about 100 searches). Typed into a masked field and saved encrypted for your Windows account; empty clears it. `/profile push keys` copies it and a plain `/profile reset` keeps it. Never written to the log.",
        SettingsField.YouTubeSearchMaxResults => "How many videos (or playlists, or channels) a search lists (1–20), for the model and in `/youtube`'s picker. The quota cost is the same whatever the count.",
        SettingsField.YouTubeOpenLinksIn => "Where a YouTube video plays: `youtube-window`, `browser-window`, `default-browser` or `webui-window`. It covers `youtube_play`, `/youtube play` and its lists, `open_url` on a video or playlist link while *YouTube tools* is on, and the video and playlist links the video window opens (anything else it opens goes to your default browser). `youtube-window` is the app's video window. `browser-window` opens the video in the app's Browser window (your default browser where there is none, as headless), and `default-browser` in your default browser; either way the model can't see or control it after. `webui-window` plays it in the Web UI's YouTube tab on your phone or browser while *Web UI YouTube controls* is on, and in the video window otherwise; it goes to the tab shown most recently, any open Web UI page jumps to that tab, and with none in view the video waits for one. While the Web UI isn't serving, it plays in the video window. The YouTube tab runs YouTube's player script in the Web UI's own page, so while it is open that script can do what the page can, though never read the sign-in cookie.",
        SettingsField.YouTubeAutoplay => "Whether a played video starts at once, sound included, or waits cued until you or the model press play.",
        SettingsField.YouTubeVoice => "What a playing video does while the app speaks a reply (from its first word to its last) or listens to you (push-to-talk, or after the wake phrase): `pause`, `duck` or `none`. `pause`: it pauses and plays on after. `duck`: it turns down to 15 % and back up after (speech input still hears it). `none`: it plays on. Only what the app did is undone: a video you paused stays paused.",
        SettingsField.YouTubeSearchOrder => "The order a search lists in unless it names one: `relevance` (YouTube's own ranking), `date` (newest first), `views`, `rating` or `title`. The model's `order` and `/youtube search --order` override it for one search.",
        SettingsField.YouTubeSafeSearch => "How much restricted content a search leaves out unless it names a level: `none`, `moderate` (YouTube's own default) or `strict`. The model's `safe_search` and `/youtube search --safe` override it for one search.",
        SettingsField.YouTubeRegion => "A two-letter country code (`US`, `GB`, `DE`) a search asks for: what can be watched and is popular there. Empty for any region. The model's `region` and `/youtube search --region` override it for one search.",
        SettingsField.YouTubeLanguage => "A language code (`en`, `es`, `zh-Hans`) a search favors: results in it rank higher, the rest are still listed. Empty for any language. The model's `language` and `/youtube search --lang` override it for one search.",
        SettingsField.PrintTools => "Offers `list_printers` and `print_file` to the model. `/print` works either way. The top of its on/off page (`/tools print`, the toolbar's 🖨️) has a **printer** button (`p`) that opens *Print default printer*; Esc there comes back.",
        SettingsField.PrintActionPolicy => "What the model may print. `off`: it may list the printers but never print. `ask`: every print waits for your yes, asked with the file, the printer, the pages and the copies; in a headless run, it is refused. `allow`: it prints without asking. `/print` never asks.",
        SettingsField.PrintDefaultPrinter => "The printer a print goes to when none is named, picked from the installed printers.",
        SettingsField.PrintFontSize => "The body text size for a printed listing or Markdown file (6–24 pt); headings scale from it.",
        SettingsField.PdfEngine => "What makes a PDF for `convert_to_pdf` and `/pdf`. `auto`: Edge, Chrome or Brave when one is found, else Microsoft Print to PDF, which also takes over when the browser fails. `browser`: the browser only. `printer`: Microsoft Print to PDF only, so Markdown, text and pictures in black and white, never HTML or a web page. Editing a PDF (`pdf_edit`, `/pdf merge|extract|rotate|delete`) needs the browser whatever this says.",
        SettingsField.EmbeddedModels => "The catalog: each model with its size and state. Enter on an installed model offers *Use now* and *Remove*; on any other, *Install* (and *Remove* for a partial download). Remove asks first, stops a download or a server of that model, and deletes its folder (its vision projector and drafter too, unless another model on disk shares them); if it was the saved LLM, *LLM URL* and *LLM model* are cleared. Using or installing a model closes the settings and connects. The title row's buttons filter and order the list, and combine: **size** (`s`) steps from any to models up to 8GB and up to 16GB, the whole size (weights, projector and drafter); **show** (`i`) steps from all to the installed ones and the uninstalled ones (a partial download is uninstalled); **drafter** (`d`) keeps models with a drafter; **sort** (`o`) switches between name and size order; **uncensored** (`x`) shows only the uncensored builds, which are otherwise hidden. `/server` and the startup picker have the size, drafter, sort and uncensored buttons too.",
        SettingsField.EmbeddedBackend => "Which llama.cpp build runs the model: `auto` (CUDA with an NVIDIA driver 580 or newer, else Vulkan, else the CPU), `cuda`, `vulkan` or `cpu`. The row shows what `auto` picked and why.",
        SettingsField.EmbeddedContextSize => "The server's context window in tokens (how much conversation the model can hold). 0 means **fit**: the largest context that fits beside the model with every layer on the GPU (within *Embedded VRAM budget (%)*), from the model's own window (128K for Gemma 4 E2B/E4B, 256K for the larger models) down to 4,096. Otherwise 512–262,144, never shrunk.",
        SettingsField.EmbeddedGpuLayers => "How many of the model's layers go on the GPU: `auto` (as many as the free VRAM holds), `all`, or a number (0 runs on the CPU).",
        SettingsField.EmbeddedVision => "Loads the model's vision projector so it can read images (about 1 GB more memory for most models, under 200 MB for the 12Bs, 2 GB for Muse Glimmer). Off, an image sent to the embedded model is refused.",
        SettingsField.LlmReasoningEstimate => "How the *Reasoning* count in `/usage` is filled in when the server streams the model's thinking but does not count it (llama.cpp, including the embedded LLM, and Ollama). `chars` divides the thinking's characters by 4. `tokenize` asks llama.cpp's `/tokenize` for the exact count (one short request after each reply), and falls back to `chars` where that is not available. `off` shows `—`. An estimate shows as `~1,234`. When the server gives its own count, that is always used as it is.",
        SettingsField.EmbeddedLlmServer => "Offers the embedded models. Off, `/server` lists none and `/server embedded` refuses; a saved embedded URL counts as none (the app looks for a server as if the URL were blank), and a running embedded server stops. Installed models stay on disk. The Connect a model page's *Download an embedded model* turns it on once the model picked is ready, a plain `/profile reset` keeps it with an embedded URL, and `--url embedded` (or `NEONSIDEKICK_LLM_URL=embedded`) turns it on for that run.",
        SettingsField.EmbeddedDrafter => "Speeds up replies with multi-token prediction (MTP): the model drafts a few tokens ahead, then checks them, so the text is the same, only faster. Gemma 4 models use a small drafter file downloaded with the model; Qwen3.8 has it built in; Muse Glimmer uses a 1.6 GB DFlash drafter that drafts 16 tokens at a time. Off, no drafter is loaded or downloaded and the model writes one token at a time. Turn it off if a model misbehaves with it.",
        SettingsField.ShowPerformanceBar => "A checklist of the meters on the performance bar, updated once a second. The meters: **CPU**, **RAM**, **GPU**, **VRAM**, **NET** (network use as a share of the link speed), **NET↓** and **NET↑** (download and upload rates in bits per second) and **PROC** (the model's background processes still running; `/process` lists them). `/perfbar edit` opens it too. Enter or Space flips one; Delete unchecks it; `a` / `n` / `d` check all, none or the default (which puts the order and sides back too); none hides the bar. The checklist has three groups, *Pinned left*, *Pinned center* and *Pinned right*: Shift+←/→ (or Alt+←/→) pins the meter under the cursor a group over, Shift+↑↓ (or Alt+↑↓) moves it a place (crossing into the next group at its edge) and Shift+Home/End to its group's top or bottom; a bar never pinned is centered. The title row's **look:** button (`l`) steps the look (text, gauge, led), and `/perfbar text`, `gauge` or `led` picks it. Values turn amber from 60 % and red from 85 %; a meter the machine cannot read is left out. On a narrow row the meters shrink, then fall back to the numbers, then the side groups give way; the center wins. A double-click or a right-click on the bar opens `/settings`. `/perfbar` hides the bar or shows it again.",
        SettingsField.ShowHomeBar => "The home bar: a row of chips under the performance bar, each a Home Assistant room or device (or the shopping list's 🛒), that shows its state and switches it. Enter (or `/homebar edit`) opens the picker. Its first tab, the bar, lists the chips in three groups, *Pinned left*, *Pinned center* and *Pinned right*: Shift+←/→ pins the chip under the cursor a group over, Shift+↑/↓ moves it, Shift+Home/End to its group's top or bottom, Delete removes it, and Enter offers the same as a list plus *Rename on the bar…* (an alias; blank shows the emoji alone) and *Change emoji…*; the tab's last row, *+ Add divider*, adds a dim │. The other tabs (Rooms, Lights, Switches, Sensors, Climate, Media, Scenes, Security, Zones, Other, Shopping) add or remove an item with Space or Enter; typing filters by name, id, area or label. On the bar a click shows a chip's state, a double-click acts (a light toggles, a room's lights go off or on, a scene runs, a player plays or pauses, a cover closes or opens) and a right-click opens its pane. Unlocking a lock, opening a garage, gate or door, and disarming an alarm ask first. The rooms and devices need *Home Assistant URL* and *Home Assistant API key*, not *Home Assistant tools*; the 🛒 chip needs neither. A bar never pinned is centered; on a narrow row the names shrink first, then the side groups give way, then the center pages behind ‹ ›. A double-click or a right-click on the blank space opens `/settings`. `/homebar` hides the bar or shows it again.",
        SettingsField.BarOrder => "The order of the bars under the input line, top to bottom: **Hints bar** (the keys' hints, while there is one), **Status bar** (the busy row while a reply runs), **Tool bar**, **Performance bar** and **Home bar**. Enter opens the list: Shift+↑/↓ (or Alt+↑/↓) moves the bar under the cursor a place and Shift+Home/End to the top or bottom, and the pane redraws at once; `d` (*default* on the title row) puts the order back. Only the order: each bar's own row shows or hides it, and one that is off keeps its place. A short window still drops the home bar first, then the performance bar, then the toolbar; the Hints bar goes last.",
        SettingsField.EmbeddedVramBudget =>"How much of the GPU's memory the embedded server may fill: `off` (llama.cpp leaves 1 GiB free on each GPU) or 50–99 % of the card with the most memory. It adjusts only what is left to fit: with *Embedded context length* 0 the context shrinks first, then, with *Embedded GPU layers* `auto`, layers move to the CPU, which slows replies sharply; so it works best with context 0. It is measured when the server starts. CUDA and Vulkan only; a change restarts the server.",
        SettingsField.EmbeddedHfDownloadType => "How a model's files are downloaded from Hugging Face. `parallel` fetches each file over 8 connections at once (about twice as fast as one) and joins the parts before the checksum. `single` uses one connection. A download already under way carries on the way it started.",
        SettingsField.BotChatMultiEmbedded => "Only with *Botchat LLM mode* `multi`. It decides what a bot gets when its profile names a different embedded model from the one running. `parent-server`: one embedded server; the bot uses the running model (this profile's, or with none running, the first embedded bot's), with a warning naming the model it wanted. `multi-server`: an extra `llama-server` for each other embedded model. They start one after another, each under that bot's profile's Embedded settings (backend, context, GPU layers, VRAM budget, vision, drafter), so each fits into the memory the ones before it left. The running server is never restarted, and a bot whose server does not start sits the chat out. Two bots on one model share its server.",
        SettingsField.BotChatMultiEmbeddedKill => "On: the extra servers from `multi-server` stop when the chat ends, however it ends. Off, they keep running until `/botchat --kill` or you quit, and a later botchat naming the same models reuses them. An advisor's extra server is never stopped by either.",
        SettingsField.ClaudeCodeServer => "Offers Claude Code on `/server` while it is found (*Claude Code executable*, or the PATH). If it is off (or Claude Code is gone) while it is the saved LLM URL, the app scans for a server as if the URL were blank, and a running Claude Code server stops.",
        SettingsField.OracleTools => "Offers the Oracle tools (connections, tables, columns, describe, relationships, indexes, query) over the connections in `oracle.json`, once one is defined. Each connection is held to its one schema (its `schema`, else the user's own): a statement naming another, or the dictionary's whole-database views (`ALL_*`, `DBA_*`, `CDB_*`, `V$`), is refused. The top of its on/off page (`/tools oracle`, the toolbar's 🔮) has an **offered** button (`o`) that shows how many are offered and opens *Oracle connections offered*.",
        SettingsField.OracleMode => "Whether the Oracle tools may change data: `read-only` or `read-write`. `read-only`: the Oracle tools only read. `read-write`: `oracle_execute` is offered too, on the connections whose entry in oracle.json says `\"access\": \"readwrite\"` (the default is `read`; the wizard asks) — one statement per call of the kinds *Oracle statements allowed* ticks, committed as it runs. Each change asks first: Deny, Allow once, or Allow for this session (that connection, until the session ends); a read asks nothing and runs read-only. COMMIT/ROLLBACK/SAVEPOINT/SET TRANSACTION, ALTER SESSION/SYSTEM, GRANT/REVOKE, users, roles, profiles, tablespaces, directories, database links (@ anywhere), LOCK TABLE, EXECUTE IMMEDIATE, RETURNING … INTO and the denied packages (UTL_FILE, UTL_HTTP, DBMS_SQL, DBMS_SCHEDULER…) stay refused. Never offered headless or in plan mode; every change is written to the log.",
        SettingsField.OracleStatementsAllowed => "Under *Oracle mode* `read-write`: the kinds of statement `oracle_execute` may run, ticked on a checklist. The kinds: changing data (INSERT, UPDATE, MERGE), deleting (DELETE, TRUNCATE, a MERGE that deletes), creating (CREATE TABLE, INDEX, VIEW, SEQUENCE, SYNONYM, TYPE), changing structure (ALTER TABLE, INDEX, VIEW, SEQUENCE; RENAME; COMMENT ON), dropping (DROP …), upkeep (ANALYZE), procedures and triggers (CALL, an anonymous BEGIN … END or DECLARE block, and making or changing a procedure, function, package, trigger or type body, whose code runs later) and reading (SELECT). A statement needs the kind of every change in it. `a` / `n` / `d` pick all, none or the default (changing data, creating, reading). With none ticked, `oracle_execute` is not offered.",
        SettingsField.OracleConnectionsOffered => "A checklist of the connections in both `oracle.json` files, as *SQL connections offered* is for `sql.json`: nothing is offered until you tick it.",
        SettingsField.OracleSetPassword => "Pick a connection and type its password, masked. It is saved to that connection's store: encrypted in its `oracle.json`, or in Windows Credential Manager.",
        SettingsField.OracleAddConnection => "A wizard for a new connection, one page per choice, or to edit a saved one (as *SQL add/edit connection* does). Its *Schema* is the one the connection is held to (the user's own when empty). It can **test** the draft before saving it: who it signs in as, the server's version, a warning when the account could change data, and the other schemas it could read.",
        SettingsField.OraclePercentMention => "Typing `%` and part of a name also lists the Oracle connections, each marked `Oracle ·`; a pick writes `%name` as text.",
        SettingsField.OracleQueryMaxRows => "How many rows `oracle_query` returns unless the call says otherwise (1–100,000). Past that, the header says more exist.",
        SettingsField.OracleQueryTimeoutSeconds => "How long one Oracle tool's statement may run on the server (1–600 s).",
        SettingsField.OracleConnectionsProfile => "Enter opens this profile's `oracle.json` in your editor (made with commented examples when missing). The row shows how many connections it has.",
        SettingsField.OracleConnectionsGlobal => "Enter opens the global `oracle.json` (in the home folder's `configs`), which every profile reads, in your editor. On a name clash, the profile's entry wins.",
        SettingsField.MySqlTools => "Offers the MySQL tools (connections, tables, columns, describe, relationships, indexes, query) over the connections in `mysql.json`, once one is defined. They work against MySQL 8.0.16+ and MariaDB 10.2+. Each connection reaches its own database alone: a statement naming another, or the server's own (`information_schema`, `mysql`, `performance_schema`, `sys`), is refused, and another database needs a connection of its own. The top of its on/off page (`/tools mysql`, the toolbar's 🐬) has an **offered** button (`o`) that shows how many are offered and opens *MySQL connections offered*.",
        SettingsField.MySqlMode => "Whether the MySQL tools may change data: `read-only` or `read-write`. `read-only`: the MySQL tools only read. `read-write`: `mysql_execute` is offered too, on the connections whose entry in mysql.json says `\"access\": \"readwrite\"` (the default is `read`; the wizard asks) — one statement per call of the kinds *MySQL statements allowed* ticks, committed as it runs. Each change asks first: Deny, Allow once, or Allow for this session (that connection, until the session ends); a read asks nothing and runs read-only. START TRANSACTION/COMMIT, SET, USE, GRANT/REVOKE, LOAD DATA, INTO OUTFILE, LOCK, PREPARE/EXECUTE, HANDLER, FLUSH/KILL, DEFINER = and CREATE or DROP of a database, user, role, server or event stay refused. Never offered headless or in plan mode; every change is written to the log.",
        SettingsField.MySqlStatementsAllowed => "Under *MySQL mode* `read-write`: the kinds of statement `mysql_execute` may run, ticked on a checklist. The kinds: changing data (INSERT, UPDATE, REPLACE), deleting (DELETE, TRUNCATE), creating (CREATE TABLE, INDEX, VIEW, SEQUENCE), changing structure (ALTER TABLE, VIEW, SEQUENCE; RENAME TABLE), dropping (DROP …), upkeep (ANALYZE, OPTIMIZE, CHECK, REPAIR, CHECKSUM TABLE), procedures and triggers (CALL, and making or changing a procedure, function or trigger, whose code runs later) and reading (SELECT). A statement needs the kind of every change in it. `a` / `n` / `d` pick all, none or the default (changing data, creating, reading). With none ticked, `mysql_execute` is not offered.",
        SettingsField.MySqlConnectionsOffered => "A checklist of the connections in both `mysql.json` files, as *SQL connections offered* is for `sql.json`: nothing is offered until you tick it.",
        SettingsField.MySqlSetPassword => "Pick a connection and type its password, masked. It is saved to that connection's store: encrypted in its `mysql.json`, or in Windows Credential Manager.",
        SettingsField.MySqlAddConnection => "A wizard for a new connection, or to edit a saved one (as *SQL add/edit connection* does). The database is required: the connection reaches that one alone. It can **test** the draft before saving it: who it signs in as, the server's version, a warning when the account's grants could change data, and the other databases the account could reach.",
        SettingsField.MySqlPercentMention => "Typing `%` and part of a name also lists the MySQL connections, each marked `MySQL ·`; a pick writes `%name` as text.",
        SettingsField.MySqlQueryMaxRows => "How many rows `mysql_query` returns unless the call says otherwise (1–100,000). Past that, the header says more exist.",
        SettingsField.MySqlQueryTimeoutSeconds => "How long one MySQL tool's statement may run (1–600 s), enforced on the server and by the driver.",
        SettingsField.MySqlConnectionsProfile => "Enter opens this profile's `mysql.json` in your editor (made with commented examples when missing).",
        SettingsField.MySqlConnectionsGlobal => "Enter opens the global `mysql.json` (in the home folder's `configs`), which every profile reads, in your editor. On a name clash, the profile's entry wins.",
        SettingsField.UncTools => "Offers the UNC tools over the shares in `unc.json`, once one is defined: `unc_shares`, `unc_search`, `unc_info`, `unc_read`, and `unc_fetch` while *File tools* is on. The top of its on/off page (`/tools unc`, the toolbar's 🔗) has an **offered** button (`o`) that shows how many are offered and opens *UNC shares offered*.",
        SettingsField.UncWrites => "The master switch for every change on a share. Off, every share is read-only. On, a share whose `access` is `readwrite` also gets `unc_write`, `unc_patch`, `unc_create_directory`, `unc_move`, `unc_copy`, `unc_delete` (off by default in the Offered tab) and `unc_put`. Changes there are permanent.",
        SettingsField.UncSharesOffered => "A checklist of the shares in both `unc.json` files, as *SQL connections offered* is for `sql.json`: nothing is offered until you tick it.",
        SettingsField.UncSetPassword => "Pick a runas share and type its password, masked. It is saved to that share's store: encrypted in its `unc.json`, or in Windows Credential Manager.",
        SettingsField.UncAddShare => "A wizard for a new share, or to edit a saved one (as *SQL add/edit connection* does). It can **test** the draft before saving it by listing its root under its account.",
        SettingsField.UncStarMention => "Typing `*` and part of a name on the input line lists the offered shares (path, read-write, description); a pick writes `*name` as text. The database connections keep `%`.",
        SettingsField.UncSharesProfile => "Enter opens this profile's `unc.json` in your editor (made with commented examples when missing).",
        SettingsField.UncSharesGlobal => "Enter opens the global `unc.json` (in the home folder's `configs`), which every profile reads, in your editor. On a name clash, the profile's entry wins.",
        SettingsField.EmbeddedVramOnly => "Keeps the embedded model in the GPU's memory: every layer goes on the GPU (whatever *Embedded GPU layers* says; with *Embedded context length* 0 the context shrinks to fit instead). If any of it still lands in system RAM (layers left on the CPU, a buffer that could not be allocated, memory the NVIDIA driver moved to shared GPU memory), the server stops and the connect says what to lower. Refused on the CPU backend, on Vulkan with an integrated GPU, and when llama-server does not report where it put the layers. To keep the NVIDIA driver from moving memory: in the NVIDIA Control Panel, *Manage 3D settings* › *Program Settings*, add `llama-server.exe` (under the home folder's `llama\\`) and set *CUDA - Sysmem Fallback Policy* to *Prefer No Sysmem Fallback*.",
        SettingsField.MenuMaxHeight => "The most of the window a menu or info pane may take, its rules and the status bar included: `half`, `three-quarters` or `full` (all but one row). It applies to `/settings`, `/tools`, `/skills`, `/mcp`, `/help`, `/usage`, `/cwd browse` and the like. A longer list scrolls inside it. Every tab of a pane keeps the height of its tallest tab, so the pane does not jump as you tab through it.",
        SettingsField.ProjectFile => "Reads `NEON.md` (else `AGENTS.md`, else `CLAUDE.md`) in the working directory into the prompt as project notes. Off, those files are ignored. Needs *Agent skills*.",
        SettingsField.ImageEditQuality => "The quality `image_edit` writes a JPEG (or JPEG XL, HEIF) at when the model gives none (1–100), and where `max_kb` starts lowering it from.",
        SettingsField.ImageEditMetadata => "The metadata `image_edit` keeps unless the model asks otherwise: `none`, `basic` or `all`. `none` drops it all (no camera, date or place); `basic` keeps author, copyright, title, comment, date taken, camera and exposure; `all` also keeps the GPS position, so the picture says where it was taken.",
        SettingsField.ImageEditMode => "Where an edited picture goes: `beside-original` or `overwrite-original`. `beside-original` writes a new file beside the source (`photo-edited.png`; `image_edit` uses *Image edit output folder* when it is set); `overwrite-original` replaces the source (a format change writes `photo.jpg` and deletes `photo.png`). It rules the picture windows' right-click menu (`/view`, `/view --thumbs`) and `image_edit` when the model names no `to`. No confirmation either way.",
        SettingsField.ImageEditOutputFolder => "Where `image_edit` writes when the model names no `to`: a folder under the profile's `images` folder, made on first use. Empty writes beside the source picture.",
        SettingsField.PastedImagesFolder => "The folder under the profile's `images` folder a picture pasted from the clipboard is saved in when its message is sent (`pasted\\pasted-20261009-142233.png`), made on first use. The message tells the model the file's path, so its picture tools can use it. Empty uses the `images` folder itself. A dropped file is not copied. `/pasted view`, `thumbs` and `purge` open or empty it.",
        SettingsField.FileSearchMaxResults => "The most rows one `search_files` or `unc_search` call returns, whatever its `limit` asks (1–5000): hits, listed entries, matching names or recent files. A call without `limit` still gets 50 hits, 200 entries, 100 names or 10 recent files.",
        SettingsField.WebDownloadMaxMegabytes => "The largest file `download_file` saves (1–102,400 MB). The file streams to disk, so a big cap costs disk space, not memory. A download that sends nothing for 60 seconds is dropped, and a partial file never stays.",
        SettingsField.QueryResultMaxChars => "The most characters of table one `sql_query`, `oracle_query` or `mysql_query` answer carries (1,000–1,000,000); the rows past it are left off and the header says how many fit. One setting for those three.",
        SettingsField.ReflectionInstalledSkills => "What a reflection may do to a skill installed with `/skills add`. `read-only` refuses any change and asks it to write a companion skill instead (under *Reflection mode* `update-only` it leaves the skill as it is and writes nothing), so a later update from the same source stays clean. `allow-and-mark` lets it change the skill; an update from its source then warns first, and the skill's revert on `/skills` can bring the earlier version back.",
        SettingsField.DockerTools => "Offers the Docker tools: `docker_containers`, `docker_logs`, `docker_inspect`, `docker_stats`, `docker_resources` and `docker_compose`. They are offered whether Docker Desktop runs or not (they say when it does not). `/docker` works either way. The top of its on/off page (`/tools docker`, the toolbar's 🐳) has a **manage** (`m`) button that opens `/docker`'s container list; Esc there comes back.",
        SettingsField.EventLogTools => "Offers the event-log tools: `eventlog_logs`, `eventlog_search`, `eventlog_summary` and `eventlog_event`, read-only, over the computers ticked in *Event log computers offered* and the `.evtx` files in the working directory. `/eventlog` works either way. The top of its on/off page (`/tools eventlog`, the toolbar's 🪵) has an **offered** button (`o`) that shows how many computers are ticked and opens *Event log computers offered*. Windows only.",
        SettingsField.EventLogComputersOffered => "A checklist of the computers the event-log tools and `/eventlog` may read: `local` (this PC, built in) first, then each computer of both `eventlog.json` files. Until you change it, `local` alone is ticked; untick everything and the tools read `.evtx` files alone. Windows only.",
        SettingsField.EventLogSetPassword => "Pick a runas computer and type its password, masked. It is saved to that computer's store: encrypted (DPAPI) in its `eventlog.json`, or in Windows Credential Manager. Windows only.",
        SettingsField.EventLogAddComputer => "A wizard for a new computer, or to edit a saved one (as *UNC add/edit share* does); for `local`, it asks only for its logs, detail and description. It can **test** the draft before saving it by reading the newest System event under its account. Windows only.",
        SettingsField.EventLogMaxEvents => "How many events `eventlog_search` lists when the model names no `limit`, and a page of `/eventlog`'s list (1–100). Windows only.",
        SettingsField.EventLogScanLimit => "The most events one search or summary looks at before it stops and says how far back it got (1,000–30,000); a remote computer gets a quarter of it, and every search 10 seconds at most. Windows only.",
        SettingsField.EventLogComputersProfile => "Enter opens this profile's `eventlog.json` in your editor (made with commented examples when missing). Each entry is a computer: its `host`, `auth` (`windows` or `runas`), `logs` and `detail` (`redacted` or `full`); a runas password goes to DPAPI or Credential Manager (`cmdkey`). Windows only.",
        SettingsField.NetworkTools => "Offers the network tools: `net_dns`, `net_ping`, `net_trace`, `net_port` and `net_tls`, read-only, each on one host (no ranges or blocks), judged by *Network tools reach* and the host lists and counted against the turn's budget; `net_certs` too with *Network certificate stores*. `/net` works either way.",
        SettingsField.NetworkToolsReach => "Where the network tools may reach: `same-as-web` (the default) follows *Web browser network mode*; `internet`, `lan` or `both` set it for these tools alone. The DNS servers this machine uses are never judged; one a call names is.",
        SettingsField.NetworkMaxHostsPerTurn => "The most distinct hosts the network tools check in one turn (1–64): two names for one address count once, a sweep of addresses counts each, a refused or unresolved name counts too. A Ralph run, a `/loop` or a camera watch gets this many for the whole run. Past it a call is refused. `/net` is never counted.",
        SettingsField.NetworkMaxPortsPerTurn => "The most distinct host:port pairs the network tools check in one turn (1–256); one budget for a whole automation run, as for hosts. Past it a call is refused.",
        SettingsField.NetworkAllowedHosts => "Hosts the network tools may check: names, globs of whole labels (`*.corp.example`) and CIDR blocks (`10.20.0.0/16`, `fd00::/8`). Empty allows anything the reach admits; any entry makes it the matches alone. A bad entry is refused as you type it.",
        SettingsField.NetworkDeniedHosts => "Hosts the network tools never check, in the allowed list's forms; a match wins over everything else. A name is matched as typed and by each address it resolves to.",
        SettingsField.NetworkCertificateStores => "Also offers `net_certs`, which lists this machine's certificate stores (subjects, issuers, end dates, whether a private key is there; nothing exported). Off by default, so the connection checks never show personal certificates. `/net certs` works either way.",
        SettingsField.ServiceTools => "Offers the services tools: `service_list` and `service_info`, read-only, over the computers ticked in *Service computers offered*; with *Service writes* also `service_control` and `service_start_type`. `/services` works either way. Windows only.",
        SettingsField.ServiceWrites => "Lets the model start, stop, restart or change the start type of a service, each call asking you first, only on a computer whose `services.json` entry says `\"access\": \"readwrite\"` and names the service in `control`, within its `controlActions`; never a driver or a protected service. `service_start_type` is off in a new profile's Offered tab even then. Never headless. Off by default. Windows only.",
        SettingsField.ServiceComputersOffered => "A checklist of the computers the services tools and `/services` may reach: `local` (this PC, built in) first, then each computer of both `services.json` files. Until you change it, `local` alone is ticked. Windows only.",
        SettingsField.ServiceSetPassword => "Pick a runas computer of `services.json` and type its password, masked: saved encrypted (DPAPI) in the file, or in Windows Credential Manager. Windows only.",
        SettingsField.ServiceAddComputer => "A wizard for a new computer of `services.json`, or to edit a saved one: its host and sign-in, its access, the services it shows, and under readwrite what may be changed, the actions allowed and its own protected list. It can **test** the draft by listing the services under its account. Windows only.",
        SettingsField.ServiceComputersProfile => "Enter opens this profile's `services.json` in your editor (made with commented examples when missing): each entry's `host`, `auth`, `access`, `services`, `control`, `controlActions`, `protected` and `detail`. Windows only.",
        SettingsField.ServiceComputersGlobal => "Enter opens the global `services.json` (in the home folder's `configs`), which every profile reads, in your editor. On a name clash, the profile's entry wins. Windows only.",
        SettingsField.MonitorTools => "Offers the monitor tools: `monitor_list`, `monitor_input` (switch a monitor's input over DDC/CI) and `monitor_layout` (extend, duplicate, only one monitor, make one primary); both changes ask first, and only with the pane (never headless). The names given to inputs and the hidden ones are set from a monitor's *Input names…* on the 🖥️ pane and kept by a plain `/profile reset`. `/monitor` works either way. Windows only.",
        SettingsField.TaskTools => "Offers the task tools: `task_list` and `task_info`, read-only, over the computers ticked in *Task computers offered*; with *Task writes* also `task_control`. `/tasks` works either way. Windows only.",
        SettingsField.TaskWrites => "Lets the model run, end, enable or disable a scheduled task, each call asking you first, only on a computer whose `tasks.json` entry says `\"access\": \"readwrite\"` and matches the task in `control`, within its `controlActions`; Windows' own tasks and privileged ones are guarded. Never headless. Off by default. Windows only.",
        SettingsField.TaskComputersOffered => "A checklist of the computers the task tools and `/tasks` may reach: `local` first, then each computer of both `tasks.json` files. Until you change it, `local` alone is ticked. Windows only.",
        SettingsField.TaskSetPassword => "Pick a runas computer of `tasks.json` and type its password, masked: saved encrypted (DPAPI) in the file, or in Windows Credential Manager. Windows only.",
        SettingsField.TaskAddComputer => "A wizard for a new computer of `tasks.json`, or to edit a saved one: its host and sign-in, its access, the folders it shows, and under readwrite what may be changed, the actions allowed and whether privileged tasks may be run. It can **test** the draft. Windows only.",
        SettingsField.TaskComputersProfile => "Enter opens this profile's `tasks.json` in your editor (made with commented examples when missing): each entry's `host`, `auth`, `access`, `folders`, `control`, `controlActions`, `privileged` and `detail`. Windows only.",
        SettingsField.TaskComputersGlobal => "Enter opens the global `tasks.json` (in the home folder's `configs`), which every profile reads, in your editor. On a name clash, the profile's entry wins. Windows only.",
        SettingsField.DirectoryTools => "Offers the directory tools: `ad_user`, `ad_group`, `ad_computer`, `ad_find`, `ad_ou` and `ad_domain`, over the domains ticked in *Directory domains offered*. The directory is never written (nothing in the app can); a list's `to` writes a CSV in the working directory, only with *File tools* on and never in plan mode. `/ad` works either way.",
        SettingsField.DirectoryDomainsOffered => "A checklist of the domains the directory tools and `/ad` may read: `current` (this PC's own, when it is joined) first, then each domain of both `ad.json` files. Until you change it, `current` alone is ticked on a joined PC, and nothing on another.",
        SettingsField.DirectorySetPassword => "Pick a runas domain of `ad.json` and type its password, masked: saved encrypted (DPAPI) in the file, or in Windows Credential Manager. A password the domain refuses is not tried again until it is set here anew.",
        SettingsField.DirectoryAddDomain => "A wizard for a new domain of `ad.json`, or to edit a saved one: its DNS name, the server to ask, where to search, LDAPS or not, the sign-in and the detail. It can **test** the draft (the bind, the policy, a user read).",
        SettingsField.DirectoryDomainsProfile => "Enter opens this profile's `ad.json` in your editor (made with commented examples when missing): each entry's `domain`, `server`, `baseDn`, `tls`, `auth` and `detail`.",
        SettingsField.DirectoryDomainsGlobal => "Enter opens the global `ad.json` (in the home folder's `configs`), which every profile reads, in your editor. On a name clash, the profile's entry wins.",
        SettingsField.EventLogComputersGlobal =>"Enter opens the global `eventlog.json` (in the home folder's `configs`), which every profile reads, in your editor. On a name clash, the profile's entry wins; a runas password goes to DPAPI or Credential Manager (`cmdkey`). Windows only.",
        SettingsField.DockerWrites => "The master switch for the model's changes. Off, the model may only look. On, it also gets `docker_lifecycle`, `docker_pull`, `docker_remove` and `docker_prune` (the last two off by default in the Offered tab), and every one of those calls waits for your yes. Headless refuses them.",
        SettingsField.DockerEnginePipe => "The Docker engine's named pipe: `docker_engine` (Docker Desktop's), any other name, `\\\\.\\pipe\\name` or the CLI's `npipe:////./pipe/name`. Blank is the default.",
        SettingsField.DockerServers => "Offers the chosen containers in `/server`. Turning it off while one is in use stops it at the reconnect.",
        SettingsField.DockerServerContainers => "Which containers are servers: a checklist of the LLM servers the engine lists, with their state, image and ports (Enter or Space ticks one; select all or none tick the rows shown). A container is listed when its image or command holds one of *Docker server match words*, when it carries the label `neonsidekick.llm=true`, or when it is already ticked; an empty word list lists every container. A ticked name the engine no longer lists is dropped when the checklist opens, and the status line names it.",
        SettingsField.DockerServerMatchWords => "The words that make a container an LLM server in *Docker server containers*' checklist, matched in its image or its command, case ignored. The starting list holds `vllm`, `sglang`, `llama-server`, `ollama` and the other known engines. The top row adds one, Enter on one removes it after a yes, and the restore button (`r`) brings back the defaults. Empty, the checklist shows every container. The label `neonsidekick.llm=true` lists a container whatever the words.",
        SettingsField.DockerServerStopTimeoutSeconds => "How long a stopping container gets before the engine kills it (0–120 s).",
        SettingsField.DockerServerPostStopDelaySeconds => "The wait between stopping the others and starting this one, so the GPU's memory is free (0–60 s).",
        SettingsField.DockerServerReadyTimeoutSeconds => "How long a started container may take to answer on `/v1/models` (30–3600 s). Past it the switch fails and the container is left running.",
        SettingsField.DockerServerStopOnExit => "Stops the container in use when the app exits, the window's close button included. Off, it keeps running.",
        SettingsField.SttDestination => "Where what you say goes: `chat` or `draft`. `chat`: sent to the model straight away. `draft`: added to the end of the input line (after a space if needed) for you to edit and send with Enter; push-to-talk and the wake word then work with text on the line too (except a push-to-talk key of `Home`, `End`, `PageUp` or `PageDown`, which still move around the draft). Applies to an interruption's request as well.",
        SettingsField.CameraTools => "Offers `camera_capture`, which lets the model ask you for a photo. Never offered without the pane, headless, or to an embedded model without vision. `/camera` works either way. The top of its on/off page (`/tools camera`, the toolbar's 📸) has a **watch** button (`w`) that starts or stops `/camera watch`, **live** (`l`) that opens or closes the camera's window, and **snap** (`s`) and **screen** (`c`), which close the pane and run `/camera snap` or `/screen`.",
        SettingsField.CameraShutter => "Who takes the model's photo. `user`: the camera pane shows the model's request; Space takes the photo, `r` takes it again, Enter sends it, Esc declines; the Web UI offers Take and send (no preview) or Cancel at once. `model`: a pane asks Deny / Allow once / Allow for this session (cleared by `/new`, `/clear` and a profile switch), and on a yes the app takes the photo at once.",
        SettingsField.CameraPreview => "What shows the shot while you take a photo: `live`, `post` or `off`. `live`: a camera window of its own (beside the picture viewer, never in its place) shows the camera live (mirrored) while you frame the shot, then holds the photo taken. `post`: the viewer opens on the photo once it is taken. `off`: no window. The viewer never takes the keyboard from the terminal.",
        SettingsField.CameraDevice => "The camera, by the name Windows lists it under, picked from the ones connected. `(first camera)` uses the first; a camera that is not connected uses the first, with a notice.",
        SettingsField.CameraResolution => "The size the camera is asked for (`640x480`, `1280x720` or `1920x1080`). The camera runs at its own size nearest it, and a photo is scaled to fit the longer side.",
        SettingsField.CameraKeepInSessions => "Keeps camera photos in stored sessions, like any picture. Off, a stored session keeps a line naming the photo instead (the file stays in the *Camera output folder*), so a resumed session does not carry your face.",
        SettingsField.CameraWatchSeconds => "How often `/camera watch` looks (2–3600 s).",
        SettingsField.CameraWatchThreshold => "How much of the picture must change for watch mode to keep a frame (1–100). Shifts in brightness do not count. `--camera-check` prints your camera's own noise.",
        SettingsField.CameraWatchUnprompted => "Lets watch mode show the model a changed picture unasked, no more often than *Camera watch min gap (s)*, and only while no reply runs, nothing speaks and the input line is empty. Off, a changed picture rides your next message.",
        SettingsField.CameraWatchMinGapSeconds => "The least time between two unprompted watch turns (30–3600 s).",
        SettingsField.BotChatCamera => "The bots see you: the camera stays on for the chat, and each bot's turn gets a fresh picture from it. The picture comes last after the chat's own pictures (4 in all), captioned as a photo of you (User, as the chat names you) and not from any bot; the bots' instructions say the same. The pictures are kept in memory only, never saved. Only for models that read images; a camera that fails is one warning and the chat goes on without it. Read when a chat starts.",
        SettingsField.BotChatRecentContext => "Tells every bot, in its system prompt, the last 10 messages of this chat as they stood when `/botchat` began. Tool results are cut to 500 characters and pictures left out, so a topic can point at what you were just discussing. Read when a chat starts. Off, the bots know the topic alone.",
        SettingsField.WebUi => "Hosts the Web UI for this profile: a browser (a phone on the home network or your tailnet) shows the chat as it happens, sends messages, answers the panes that ask (a command's approval, `ask_user`, a yes/no, an allow, the plan, a learned skill) and ticks the shopping list. The first answer, here or there, wins. `/webui` shows the sign-in link; the browser keeps a cookie. A profile switch hands the server to the other profile's settings.",
        SettingsField.WebUiPort => "The TCP port the Web UI listens on (1024–65535). A port in use, or one Windows reserves, keeps it off with a notice; pick another. Changing it signs browsers out.",
        SettingsField.WebUiCommands => "Lets the Web UI's page run slash commands: the ones that work from a phone run, `/model`, `/reasoning` and `/rewind` show their picks as cards, the lists show on the page, and the dropdown completes commands and their words. Commands that open a window or a pane only the PC has, and a few kept for the PC (`/exit`, `/webui`, `/cmd`, `/profile`…), are refused with the reason. Off, the page sends messages alone and its dropdown offers the mentions. The Chat tab only. Off by default.",
        SettingsField.WebUiConnectionDetails => "Shows the `%` and `*` connections' notes (their server and database) in the Web UI's dropdown. Off, it names them alone. The dropdown only; the chat shows what the model says. The Chat tab only. Off by default.",
        SettingsField.WebUiBotCheckControl => "Lets a Web UI page see and drive the Browser window during a bot check, so a check met away from home can be passed from the phone. The card shows the window live, and its taps, holds, scrolls and typing go into it. Off, the page answers the allow question and Give up alone. The Chat tab only. On by default.",   // a Mac's too since 2026-10-18 (the Mac Browser plan); Windows only from 2026-10-17 until then
        SettingsField.WebUiHomeControls => "Shows the Web UI's Home tab and lets it act: its tiles toggle, its sheets and rooms run a device's actions, its scenes run, Ask the house asks Home Assistant, and the video remote plays and pauses. Unlocking, opening a garage, gate or door, and disarming still ask on the page. Off, there is no Home tab. `/ha` from the chat follows Web UI commands instead. Off by default.",
        SettingsField.WebUiChatControls => "Shows the Web UI's Chat tab: the transcript, the composer, and the PC's questions answered from the phone. Off, there is no Chat tab: the page opens on the first tab that is on (Home, then Shopping, then YouTube), or says none is on, and the phone can't answer the PC's questions. The PC is unchanged. On by default.",
        SettingsField.WebUiYouTubeControls => "Shows the Web UI's YouTube tab: it plays videos and keeps the saved list (play, resume, move, remove, save the playing one), and a video started there plays there whatever *YouTube open links in* says. Off, there is no YouTube tab, and *YouTube open links in* `webui-window` plays in the PC's video window instead. There is no tab where the app has no video window (before macOS 14). Off by default.",
        SettingsField.WebUiShoppingControls => "Shows the Web UI's Shopping tab: the shopping list, its lines added, ticked, changed and removed and the store changed from the phone. Off, there is no Shopping tab; `/shopping` at the PC and the shopping tools are unchanged. Off by default.",
        SettingsField.WebUiProfileTheme => "Dresses the Web UI's pages in the profile's theme (its accents, tones and grounds), following a `/theme` at once; your lines and the review lines take the terminal's colors. Off, the pages keep their own look. On by default.",
        SettingsField.WebUiReach => "Who may reach the Web UI: `local` (localhost only) or `lan` (your home network and your tailnet). Either way a browser signs in with the link `/webui` shows. Windows asks to let the app through its firewall the first time it serves the network.",
        SettingsField.PostgresTools => "Offers the PostgreSQL tools (connections, schemas, tables, columns, describe, relationships, indexes, query) over the connections of postgres.json this profile offers. Each connection reaches its own database alone, and one schema alone when its entry names one; the server's own catalogs (`pg_database`, `pg_roles`, `pg_stat_activity`…) are refused. They only read: the session starts read-only with a statement timeout, and every statement runs in a read-only transaction that is rolled back. The top of its on/off page (`/tools postgres`, the toolbar's 🐘) has an **offered** button (`o`) that shows how many are offered and opens *PostgreSQL connections offered*.",
        SettingsField.PostgresMode => "Whether the PostgreSQL tools may change data: `read-only` or `read-write`. `read-only`: the PostgreSQL tools only read. `read-write`: `postgres_execute` is offered too, on the connections whose entry in postgres.json says `\"access\": \"readwrite\"` (the default is `read`; the wizard asks) — one statement per call of the kinds *PostgreSQL statements allowed* ticks, committed as it runs. Each change asks first: Deny, Allow once, or Allow for this session (that connection, until the session ends); a read asks nothing and runs read-only. BEGIN/COMMIT, SET, GRANT/REVOKE, COPY, LOCK, PREPARE/EXECUTE and CREATE or DROP of a database, role, extension or server stay refused. Never offered headless or in plan mode; every change is written to the log.",
        SettingsField.PostgresStatementsAllowed => "Under *PostgreSQL mode* `read-write`: the kinds of statement `postgres_execute` may run, ticked on a checklist. The kinds: changing data (INSERT, UPDATE, MERGE), deleting (DELETE, TRUNCATE), creating (CREATE TABLE, INDEX, VIEW, SEQUENCE, TYPE, SCHEMA…), changing structure (ALTER …, COMMENT ON), dropping (DROP …), upkeep (VACUUM, ANALYZE, REINDEX, CLUSTER, REFRESH MATERIALIZED VIEW), procedures and triggers (CALL, DO, and making a function, procedure, trigger or rule, whose code runs later) and reading (SELECT). A statement needs the kind of every change in it (a WITH that deletes needs deleting). `a` / `n` / `d` pick all, none or the default (changing data, creating, reading). With none ticked, `postgres_execute` is not offered.",
        SettingsField.PostgresConnectionsOffered => "A checklist of the connections in both `postgres.json` files, as *SQL connections offered* is for `sql.json`: nothing is offered until you tick it.",
        SettingsField.PostgresSetPassword => "Pick a connection and type its password, masked. It is saved to that connection's store: encrypted in its `postgres.json`, or in Windows Credential Manager.",
        SettingsField.PostgresAddConnection => "A wizard for a new connection, or to edit a saved one (as *SQL add/edit connection* does). The database is required (the connection reaches that one alone) and a schema to hold it to is optional. It can **test** the draft before saving it: who it signs in as, a warning when the role could change data (a superuser is warned of, not refused), and what else the role could reach.",
        SettingsField.PostgresPercentMention => "Typing `%` and part of a name also lists the PostgreSQL connections, each marked `PostgreSQL ·`; a pick writes `%name` as text.",
        SettingsField.PostgresQueryMaxRows => "How many rows `postgres_query` returns unless the call says otherwise (1–100,000). Past that, the header says more exist.",
        SettingsField.PostgresQueryTimeoutSeconds => "How long one PostgreSQL tool's statement may run on the server (1–600 s), as its `statement_timeout`.",
        SettingsField.PostgresConnectionsProfile => "Enter opens this profile's `postgres.json` in your editor (made with commented examples when missing). The tools read it at their next call.",
        SettingsField.PostgresConnectionsGlobal => "Enter opens the global `postgres.json` (in the home folder's `configs`), which every profile reads, in your editor. On a name clash, the profile's entry wins.",
        SettingsField.SqliteTools => "Offers the four SQLite tools (`sqlite_databases`, `sqlite_tables`, `sqlite_describe`, `sqlite_query`) over the offered databases of `sqlite.json`. Under *SQLite sandbox files* they also reach the working directory's SQLite files. Those four only read: the file is opened read-only, `query_only` is set, and every statement runs in a transaction that is rolled back; *SQLite mode* `read-write` adds `sqlite_execute`, which may change a database. The top of its on/off page (`/tools sqlite`, the toolbar's 🪶) has an **offered** button (`o`) that shows how many are offered and opens *SQLite databases offered*. While on, the shell police refuses a command or script that reaches SQLite (under *Shell police*), and the file tools never change a database file (`.db`, `.db3`, `.sqlite`, `.sqlite3`, or one `sqlite.json` names).",
        SettingsField.SqliteMode => "Whether the SQLite tools may change data: `read-only` or `read-write`. `read-only`: the SQLite tools only read. `read-write`: `sqlite_execute` is offered too — one statement per call of the kinds *SQLite statements allowed* ticks, committed as it runs, and with `create` (creating ticked) a new database file (.db, .sqlite, .sqlite3, .db3) in the working directory under *SQLite sandbox files*. Each change asks first: Deny, Allow once, or Allow for this session (that file, until the session ends); a read (SELECT, VALUES, EXPLAIN) asks nothing and runs on the file opened read-only. ATTACH, DETACH, BEGIN/COMMIT, VACUUM INTO, `writable_schema`, `sqlite_dbpage` and `load_extension` stay refused. Never offered headless or in plan mode; every change is written to the log.",
        SettingsField.SqliteStatementsAllowed => "Under *SQLite mode* `read-write`: the kinds of statement `sqlite_execute` may run, ticked on a checklist. The kinds: changing data (INSERT, UPDATE, REPLACE), deleting (DELETE), creating (CREATE TABLE, INDEX, VIEW, TRIGGER, VIRTUAL TABLE), changing structure (ALTER TABLE), dropping (DROP …), upkeep (VACUUM, REINDEX, ANALYZE), settings (PRAGMA) and reading (SELECT, VALUES, EXPLAIN). A `WITH` counts as the statement after it. `create` needs creating. `a` / `n` / `d` pick all, none or the default (changing data, creating, reading). With none ticked, `sqlite_execute` is not offered.",
        SettingsField.SqliteDatabasesOffered => "A checklist of the databases in both `sqlite.json` files, as *SQL connections offered* is for `sql.json`: nothing is offered until you tick it.",
        SettingsField.SqliteSandboxFiles => "Lets the model also open any SQLite file inside the working directory by its path (`data/app.db`); a path outside it is refused, as for the file tools.",
        SettingsField.SqliteAddDatabase => "A wizard for a new database, or to edit a saved one (as *SQL add/edit connection* does): which `sqlite.json` (this profile's or the global one), the name, the database file and a description. Its test opens the file read-only and counts the tables before you save it, offered or hidden until ticked.",
        SettingsField.SqlitePercentMention => "Typing `%` and part of a name also lists the SQLite databases, each marked `SQLite ·`; a pick writes `%name` as text.",
        SettingsField.SqliteQueryMaxRows => "How many rows `sqlite_query` returns unless the call says otherwise (1–100,000). Past that, the header says more exist.",
        SettingsField.SqliteQueryTimeoutSeconds => "How long one SQLite statement may run before it is interrupted (1–600 s).",
        SettingsField.SqliteDatabasesProfile => "Enter opens this profile's `sqlite.json` in your editor (made with a commented example when missing). The tools read it at their next call.",
        SettingsField.SqliteDatabasesGlobal => "Enter opens the global `sqlite.json` (in the home folder's `configs`), which every profile reads, in your editor. On a name clash, the profile's entry wins.",
        SettingsField.ScreenTools => "Offers `screen_capture` and `screen_list`, which let the model see a monitor, every monitor or one window. Never offered without the pane, headless, or to an embedded model without its vision projector. `/screen` works either way. The top of its on/off page has **ask** (`a`) and **preview** (`p`) buttons that open *Screen policy* and *Screen preview*; Esc there comes back.",
        SettingsField.ScreenAsk => "Whether a capture asks first: `ask` or `allow`. `ask`: a pane names what would be captured and the model's reason; Deny, Allow once, or Allow for this session (remembered until the session ends). `allow`: taken without asking; *Screen preview* still shows what was sent.",
        SettingsField.ScreenPreview => "Opens the picture viewer on each screenshot taken (without taking the keyboard), so you see exactly what was sent.",
        SettingsField.ScreenOutputFolder => "The folder under the profile's `images` folder the screenshots are saved in, made on first use, kept out of the working directory. Empty means the `images` folder itself.",
        SettingsField.ScreenKeepInSessions => "Keeps screenshots in stored sessions, like any picture. Off, a stored session keeps a line naming the screenshot instead (the file stays in the *Screen output folder*), since a screenshot can hold anything that was on the screen.",
        SettingsField.CameraOutputFolder => "The folder under the profile's `images` folder the photos are saved in, made on first use, kept out of the working directory. Empty means the `images` folder itself; it may be any folder under it, even the ComfyUI output folder. Watch mode's double-clicked pictures go in its `.watch` subfolder.",
        _ => "",
    };
}
